function unitConverter(t){toolShell(t,`<div class="field"><label class="label" for="unit-cat">Category</label><select class="select" id="unit-cat"><option value="length">Length</option><option value="weight">Weight</option><option value="temperature">Temperature</option><option value="area">Area</option><option value="volume">Volume</option><option value="speed">Speed</option><option value="time">Time</option><option value="data">Data</option></select></div><div class="row"><div><div class="field"><label class="label" for="unit-val">Value</label><input class="input" id="unit-val" type="number" inputmode="decimal" value="1"></div><select class="select" id="unit-from"></select></div><div><div class="field"><label class="label" for="unit-out">Converted value</label><input class="input" id="unit-out" readonly></div><select class="select" id="unit-to"></select></div></div><div class="actions"><button class="btn primary" id="unit-run">Convert</button><button class="btn secondary" id="unit-swap">Swap units</button><button class="btn secondary" id="unit-clear">Reset</button></div><div id="unit-error"></div>`,`Choose a measurement category, units and value. Data units use binary multiples (1 KB = 1,024 bytes).`,['percentage-calculator','age-calculator']);const cat=$('#unit-cat'),from=$('#unit-from'),to=$('#unit-to'),val=$('#unit-val'),out=$('#unit-out');function fill(){const arr=cat.value==='temperature'?['°C','°F','K']:Object.keys(units[cat.value]);from.innerHTML=arr.map(x=>`<option>${x}</option>`).join('');to.innerHTML=arr.map((x,i)=>`<option ${i===1?'selected':''}>${x}</option>`).join('');run()}function temp(v,a,b){let c=a==='°C'?v:a==='°F'?(v-32)*5/9:v-273.15;return b==='°C'?c:b==='°F'?c*9/5+32:c+273.15}function run(){const v=parseFloat(val.value);if(!Number.isFinite(v)){out.value='';$('#unit-error').innerHTML='<div class="error">Enter a valid number.</div>';return}$('#unit-error').innerHTML='';const r=cat.value==='temperature'?temp(v,from.value,to.value):v*units[cat.value][from.value]/units[cat.value][to.value];out.value=fmt(r)}cat.onchange=fill;val.oninput=run;from.onchange=run;to.onchange=run;$('#unit-run').onclick=run;$('#unit-swap').onclick=()=>{const x=from.value;from.value=to.value;to.value=x;run()};$('#unit-clear').onclick=()=>{cat.value='length';val.value=1;fill()};fill();}
function textDiff(t){toolShell(t,`<div class="row"><div class="field"><label class="label" for="diff-a">Original text</label><textarea class="textarea" id="diff-a" placeholder="Paste the original text"></textarea></div><div class="field"><label class="label" for="diff-b">Revised text</label><textarea class="textarea" id="diff-b" placeholder="Paste the revised text"></textarea></div></div><div id="diff-error"></div><div class="actions"><button class="btn primary" id="diff-run">Compare text</button><button class="btn secondary" id="diff-clear">Clear</button></div><div class="result" id="diff-result" hidden><h3>Line-by-line difference</h3><div class="diff-output" id="diff-output"></div></div>`,`Paste the original and revised versions, then compare. Green lines were added and red lines were removed.`,['word-counter','case-converter']);$('#diff-run').onclick=()=>{const a=$('#diff-a').value,b=$('#diff-b').value,err=$('#diff-error');err.innerHTML='';if(!a&&!b){err.innerHTML='<div class="error">Enter text in at least one box.</div>';return}const A=a.split('\n'),B=b.split('\n'),n=A.length,m=B.length,dp=Array.from({length:n+1},()=>new Uint32Array(m+1));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=A[i]===B[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);let i=0,j=0,res=[];while(i<n&&j<m){if(A[i]===B[j]){res.push(['same',' ',A[i]]);i++;j++}else if(dp[i+1][j]>=dp[i][j+1]){res.push(['remove','−',A[i++]])}else res.push(['add','+',B[j++]])}while(i<n)res.push(['remove','−',A[i++]]);while(j<m)res.push(['add','+',B[j++]]);$('#diff-output').innerHTML=res.map(x=>`<div class="diff-line ${x[0]}"><span class="diff-mark">${x[1]}</span><span>${esc(x[2])||' '}</span></div>`).join('');$('#diff-result').hidden=false};$('#diff-clear').onclick=()=>{$('#diff-a').value=$('#diff-b').value='';$('#diff-result').hidden=true;$('#diff-error').innerHTML=''};}
async function callAI(task,input,options){let res;try{res=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task:task,input:input,options:options||{}})})}catch(e){throw new Error('Could not reach the AI service. Please check your connection and try again.')}let raw='';try{raw=await res.text()}catch(e){}let data=null;try{data=JSON.parse(raw)}catch(e){}if(!res.ok){if(res.status===400||res.status===413||res.status===422)throw new Error('That request could not be processed. Please shorten or adjust your input and try again.');if(res.status===429)throw new Error('The AI service is busy right now. Please wait a moment and try again.');if(res.status===401||res.status===403||res.status===404)throw new Error('The AI service is unavailable right now. Please try again later.');throw new Error('The AI service ran into a problem. Please try again in a little while.')}if(data&&typeof data==='object'){const out=data.result||data.text||data.output||data.response||data.content||data.translation||data.summary||data.caption;if(typeof out==='string'&&out.trim())return out;if(data.choices&&data.choices[0]&&data.choices[0].message&&typeof data.choices[0].message.content==='string'&&data.choices[0].message.content.trim())return data.choices[0].message.content;throw new Error('The AI service returned an empty response. Please try again.')}if(raw&&raw.trim())return raw;throw new Error('The AI service returned an empty response. Please try again.')}
function downloadText(text,name){if(!text){toast('Nothing to download yet.');return}const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);download(url,name);setTimeout(()=>URL.revokeObjectURL(url),4000)}
function aiBody(p,fields,runLabel,resultTitle){return `<span class="ai-badge">✦ AI powered</span><div class="ai-note">Your text is sent securely to the AI service only when you press the button below — never automatically — and it is not stored by this page. If the service fails, you will see a simple error here, never a made-up answer.</div>${fields}<div id="${p}-error"></div><div class="actions"><button class="btn primary" id="${p}-run">${runLabel}</button><button class="btn secondary" id="${p}-clear">Clear</button></div><div class="loading" id="${p}-loading"><span class="spinner"></span> AI is working — this can take a few seconds…</div><div class="result" id="${p}-result" hidden><h3>${resultTitle}</h3><div class="ai-output" id="${p}-output"></div><div class="actions"><button class="btn primary" id="${p}-copy">Copy result</button><button class="btn secondary" id="${p}-download">Download .txt</button><button class="btn secondary" id="${p}-clear2">Clear / Reset</button></div></div>`}
function bindAI(cfg){const p=cfg.prefix,runBtn=$('#'+p+'-run'),err=$('#'+p+'-error'),load=$('#'+p+'-loading'),res=$('#'+p+'-result'),out=$('#'+p+'-output');const FIELD_LIMITS={aiw:{'aiw-input':600},aie:{'aie-input':2000,'aie-recipient':120},ais:{'ais-input':12000},ait:{'ait-input':5000},aic:{'aic-input':1200},aip:{'aip-input':12000},aig:{'aig-input':12000},aipro:{'aipro-name':200,'aipro-features':3000},aih:{'aih-input':1200},aist:{'aist-theme':1200,'aist-chars':500}};const MAX_INPUT={aiw:600,aie:2200,ais:12000,ait:5000,aic:1200,aip:12000,aig:12000,aipro:3400,aih:1200,aist:1900};const fl=FIELD_LIMITS[p]||{};Object.keys(fl).forEach(id=>{const el=document.getElementById(id);if(el)el.maxLength=fl[id]});$$('.tool-box textarea').forEach(el=>{if(el.maxLength<0)el.maxLength=12000});$$('.tool-box input').forEach(el=>{if(el.maxLength<0)el.maxLength=1000});runBtn.onclick=async()=>{err.innerHTML='';const input=(cfg.getInput()||'').trim();if(!input){err.innerHTML='<div class="error">'+esc(cfg.emptyMsg||'Enter something first.')+'</div>';return}const maxI=MAX_INPUT[p]||8000;if(input.length>maxI){err.innerHTML='<div class="error">Your text is too long. Please keep it under '+maxI.toLocaleString()+' characters and try again.</div>';return}if(cfg.validate){const v=cfg.validate();if(v){err.innerHTML='<div class="error">'+esc(v)+'</div>';return}}runBtn.disabled=true;load.classList.add('show');res.hidden=true;try{const text=await callAI(cfg.task,input,cfg.getOptions?cfg.getOptions():{});out.textContent=text;res.hidden=false;res.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){const m=e&&e.message?String(e.message):'';const safe=['Could not reach the AI service','That request could not be processed','The AI service is busy','The AI service is unavailable','The AI service ran into a problem','The AI service returned an empty response'].some(s=>m.indexOf(s)===0);err.innerHTML='<div class="error">'+esc(safe?m:'Something went wrong. Please try again in a little while.')+'</div>'}finally{load.classList.remove('show');runBtn.disabled=false}};const cp=$('#'+p+'-copy');if(cp)cp.onclick=()=>copy(out.textContent);const dl=$('#'+p+'-download');if(dl)dl.onclick=()=>downloadText(out.textContent,cfg.filename||'hectool-ai-result.txt');function doClear(){(cfg.clearIds||[]).forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});out.textContent='';res.hidden=true;err.innerHTML='';if(cfg.onClear)cfg.onClear();const first=cfg.clearIds&&cfg.clearIds[0]?document.getElementById(cfg.clearIds[0]):null;if(first)first.focus()}const c1=$('#'+p+'-clear');if(c1)c1.onclick=doClear;const c2=$('#'+p+'-clear2');if(c2)c2.onclick=doClear;}
function aiTextWriter(t){toolShell(t,aiBody('aiw',`<div class="field"><label class="label" for="aiw-input">Topic or title</label><textarea class="textarea" id="aiw-input" style="min-height:110px" placeholder="e.g. The benefits of morning exercise for busy professionals"></textarea></div><div class="row three"><div class="field"><label class="label" for="aiw-format">Format</label><select class="select" id="aiw-format"><option value="blog post">Blog post</option><option value="article">Article</option><option value="paragraph">Paragraph</option><option value="essay">Essay</option></select></div><div class="field"><label class="label" for="aiw-length">Length</label><select class="select" id="aiw-length"><option value="short">Short (~150 words)</option><option value="medium" selected>Medium (~350 words)</option><option value="long">Long (~700 words)</option></select></div><div class="field"><label class="label" for="aiw-tone">Tone</label><select class="select" id="aiw-tone"><option value="professional">Professional</option><option value="friendly">Friendly</option><option value="casual">Casual</option><option value="formal">Formal</option><option value="creative">Creative</option></select></div></div>`,'Generate text','Your AI-written text'),`Enter a clear topic, choose format, length and tone, then generate. Review and edit the result before publishing — AI text can need fact-checking.`,['ai-paraphraser','ai-text-summarizer','ai-story-generator']);bindAI({prefix:'aiw',task:'write',filename:'hectool-ai-text.txt',emptyMsg:'Enter a topic first.',clearIds:['aiw-input'],getInput:()=>$('#aiw-input').value,getOptions:()=>({format:$('#aiw-format').value,length:$('#aiw-length').value,tone:$('#aiw-tone').value})});}
