function aiTranslator(t){const langs=['English','Urdu','Arabic','Hindi','French','Spanish','German','Chinese'];const opts=(sel)=>langs.map(l=>`<option value="${l}" ${l===sel?'selected':''}>${l}</option>`).join('');toolShell(t,aiBody('ait',`<div class="field"><label class="label" for="ait-input">Text to translate</label><textarea class="textarea" id="ait-input" placeholder="Type or paste the text here…"></textarea></div><div class="row"><div class="field"><label class="label" for="ait-from">From</label><select class="select" id="ait-from">${opts('English')}</select></div><div class="field"><label class="label" for="ait-to">To</label><select class="select" id="ait-to">${opts('Urdu')}</select></div></div><div class="actions" style="margin-top:0"><button class="btn secondary" id="ait-swap" type="button">⇄ Swap languages</button></div>`,'Translate','Your AI translation'),`Enter your text, choose the source and target languages, then translate. Use Swap to flip the direction instantly.`,['ai-text-writer','ai-paraphraser','ai-grammar-checker']);$('#ait-swap').onclick=()=>{const f=$('#ait-from'),to=$('#ait-to'),x=f.value;f.value=to.value;to.value=x};bindAI({prefix:'ait',task:'translate',filename:'hectool-ai-translation.txt',emptyMsg:'Enter text to translate first.',clearIds:['ait-input'],getInput:()=>$('#ait-input').value,getOptions:()=>{const from=$('#ait-from').value,to=$('#ait-to').value;return{from:from,to:to,source:from,target:to,sourceLanguage:from,targetLanguage:to}}});}
