function imageCropper(t){ toolShell(t, `<div class="field"><label class="label" for="crop-file">Choose image</label><input class="input" id="crop-file" type="file" accept="image/*"></div><div class="row" style="display:flex;flex-wrap:wrap;gap:8px"><div class="field"><label class="label" for="crop-top">Top margin (px)</label><input class="input" id="crop-top" type="number" min="0" value="0"></div><div class="field"><label class="label" for="crop-right">Right margin (px)</label><input class="input" id="crop-right" type="number" min="0" value="0"></div><div class="field"><label class="label" for="crop-bottom">Bottom margin (px)</label><input class="input" id="crop-bottom" type="number" min="0" value="0"></div><div class="field"><label class="label" for="crop-left">Left margin (px)</label><input class="input" id="crop-left" type="number" min="0" value="0"></div></div><div class="error" id="crop-error" style="display:none"></div><div class="actions"><button class="btn primary" id="crop-btn">Crop Image</button></div><img id="crop-preview" style="display:none;max-width:100%;height:auto" alt="Original preview"><div class="result" id="crop-dims"></div><canvas id="crop-canvas" style="display:none;max-width:100%"></canvas><div class="actions"><button class="btn secondary" id="crop-download" style="display:none">Download Cropped</button></div>`, `Upload an image, enter how many pixels to cut from each side, then Crop. Download the cropped result as PNG.`, ['image-resizer','image-compressor','image-converter']); const fileEl=t.querySelector('#crop-file'); const preview=t.querySelector('#crop-preview'); const canvas=t.querySelector('#crop-canvas'); const dims=t.querySelector('#crop-dims'); const errEl=t.querySelector('#crop-error'); const dlBtn=t.querySelector('#crop-download'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } let img=null; fileEl.addEventListener('change', function(){ hideErr(); const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const url=URL.createObjectURL(f); const im=new Image(); im.onload=function(){ img=im; preview.src=url; preview.style.display='block'; dims.textContent='Original: '+im.naturalWidth+' × '+im.naturalHeight+' px'; canvas.style.display='none'; dlBtn.style.display='none'; }; im.onerror=function(){ showErr('Could not load that image. Please try another file.'); }; im.src=url; }); t.querySelector('#crop-btn').addEventListener('click', function(){ hideErr(); if(!img){ showErr('Please choose an image first.'); return; } const top=parseInt(t.querySelector('#crop-top').value,10); const right=parseInt(t.querySelector('#crop-right').value,10); const bottom=parseInt(t.querySelector('#crop-bottom').value,10); const left=parseInt(t.querySelector('#crop-left').value,10); if([top,right,bottom,left].some(function(v){ return isNaN(v)||v<0; })){ showErr('Margins must be numbers 0 or higher.'); return; } const W=img.naturalWidth; const H=img.naturalHeight; if(left+right>=W){ showErr('Left + right margins must be less than the image width ('+W+' px).'); return; } if(top+bottom>=H){ showErr('Top + bottom margins must be less than the image height ('+H+' px).'); return; } const cw=W-left-right; const ch=H-top-bottom; canvas.width=cw; canvas.height=ch; const ctx=canvas.getContext('2d'); ctx.drawImage(img,left,top,cw,ch,0,0,cw,ch); canvas.style.display='block'; dims.textContent='Original: '+W+' × '+H+' px  |  Cropped: '+cw+' × '+ch+' px'; dlBtn.style.display='inline-block'; }); dlBtn.addEventListener('click', function(){ const a=document.createElement('a'); a.download='cropped.png'; a.href=canvas.toDataURL('image/png'); a.click(); }); }
function imageRotator(t){ toolShell(t, `<div class="field"><label class="label" for="rot-file">Choose image</label><input class="input" id="rot-file" type="file" accept="image/*"></div><div class="error" id="rot-error" style="display:none"></div><div class="actions"><button class="btn secondary" id="rot-cw">Rotate 90° CW</button><button class="btn secondary" id="rot-ccw">Rotate 90° CCW</button><button class="btn secondary" id="rot-fh">Flip Horizontal</button><button class="btn secondary" id="rot-fv">Flip Vertical</button></div><canvas id="rot-canvas" style="max-width:100%"></canvas><div class="actions"><button class="btn primary" id="rot-download" style="display:none">Download Image</button></div>`, `Upload an image, then rotate or flip it. Each click applies to the current image, so you can combine them. Download when done.`, ['image-cropper','image-filters','image-resizer']); const fileEl=t.querySelector('#rot-file'); const canvas=t.querySelector('#rot-canvas'); const errEl=t.querySelector('#rot-error'); const dlBtn=t.querySelector('#rot-download'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } let loaded=false; function snapshot(){ const tmp=document.createElement('canvas'); tmp.width=canvas.width; tmp.height=canvas.height; tmp.getContext('2d').drawImage(canvas,0,0); return tmp; } fileEl.addEventListener('change', function(){ hideErr(); const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const url=URL.createObjectURL(f); const im=new Image(); im.onload=function(){ canvas.width=im.naturalWidth; canvas.height=im.naturalHeight; canvas.getContext('2d').drawImage(im,0,0); loaded=true; dlBtn.style.display='inline-block'; }; im.onerror=function(){ showErr('Could not load that image. Please try another file.'); }; im.src=url; }); function needImage(){ if(!loaded){ showErr('Please choose an image first.'); return false; } hideErr(); return true; } t.querySelector('#rot-cw').addEventListener('click', function(){ if(!needImage()){ return; } const tmp=snapshot(); canvas.width=tmp.height; canvas.height=tmp.width; const ctx=canvas.getContext('2d'); ctx.translate(canvas.width/2,canvas.height/2); ctx.rotate(Math.PI/2); ctx.drawImage(tmp,-tmp.width/2,-tmp.height/2); }); t.querySelector('#rot-ccw').addEventListener('click', function(){ if(!needImage()){ return; } const tmp=snapshot(); canvas.width=tmp.height; canvas.height=tmp.width; const ctx=canvas.getContext('2d'); ctx.translate(canvas.width/2,canvas.height/2); ctx.rotate(-Math.PI/2); ctx.drawImage(tmp,-tmp.width/2,-tmp.height/2); }); t.querySelector('#rot-fh').addEventListener('click', function(){ if(!needImage()){ return; } const tmp=snapshot(); const ctx=canvas.getContext('2d'); ctx.clearRect(0,0,canvas.width,canvas.height); ctx.translate(canvas.width,0); ctx.scale(-1,1); ctx.drawImage(tmp,0,0); }); t.querySelector('#rot-fv').addEventListener('click', function(){ if(!needImage()){ return; } const tmp=snapshot(); const ctx=canvas.getContext('2d'); ctx.clearRect(0,0,canvas.width,canvas.height); ctx.translate(0,canvas.height); ctx.scale(1,-1); ctx.drawImage(tmp,0,0); }); dlBtn.addEventListener('click', function(){ const a=document.createElement('a'); a.download='rotated.png'; a.href=canvas.toDataURL('image/png'); a.click(); }); }
function imageFilters(t){ toolShell(t, `<div class="field"><label class="label" for="filt-file">Choose image</label><input class="input" id="filt-file" type="file" accept="image/*"></div><div class="field"><label class="label" for="filt-select">Filter</label><select class="select" id="filt-select"><option value="none">None (original)</option><option value="grayscale">Grayscale</option><option value="sepia">Sepia</option><option value="invert">Invert</option><option value="blur">Blur</option><option value="contrast">Contrast</option><option value="brightness">Brightness</option></select></div><div class="error" id="filt-error" style="display:none"></div><div class="actions"><button class="btn primary" id="filt-apply">Apply Filter</button></div><canvas id="filt-canvas" style="max-width:100%"></canvas><div class="actions"><button class="btn secondary" id="filt-download" style="display:none">Download Image</button></div>`, `Upload an image, pick a filter and Apply. Filters always start from your original image, so switching filters never stacks effects.`, ['image-cropper','image-rotator','image-converter']); const fileEl=t.querySelector('#filt-file'); const canvas=t.querySelector('#filt-canvas'); const errEl=t.querySelector('#filt-error'); const dlBtn=t.querySelector('#filt-download'); const sel=t.querySelector('#filt-select'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } let orig=null; function drawWith(filter){ canvas.width=orig.naturalWidth; canvas.height=orig.naturalHeight; const ctx=canvas.getContext('2d'); ctx.filter=filter; ctx.drawImage(orig,0,0); ctx.filter='none'; } fileEl.addEventListener('change', function(){ hideErr(); const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const url=URL.createObjectURL(f); const im=new Image(); im.onload=function(){ orig=im; drawWith('none'); dlBtn.style.display='inline-block'; }; im.onerror=function(){ showErr('Could not load that image. Please try another file.'); }; im.src=url; }); t.querySelector('#filt-apply').addEventListener('click', function(){ hideErr(); if(!orig){ showErr('Please choose an image first.'); return; } const map={none:'none',grayscale:'grayscale(1)',sepia:'sepia(1)',invert:'invert(1)',blur:'blur(4px)',contrast:'contrast(1.5)',brightness:'brightness(1.3)'}; drawWith(map[sel.value]||'none'); }); dlBtn.addEventListener('click', function(){ const a=document.createElement('a'); a.download='filtered.png'; a.href=canvas.toDataURL('image/png'); a.click(); }); }
function imageToBase64(t){ toolShell(t, `<div class="field"><label class="label" for="b64-file">Choose image</label><input class="input" id="b64-file" type="file" accept="image/*"></div><div class="result" id="b64-info"></div><img id="b64-preview" style="display:none;max-width:100%;height:auto" alt="Preview"><div class="field"><label class="label" for="b64-output">Base64 data URL</label><textarea class="textarea" id="b64-output" rows="6" readonly placeholder="Your Base64 data URL will appear here…"></textarea></div><div class="result" id="b64-first"></div><div class="actions"><button class="btn primary" id="b64-copy">Copy Base64</button></div>`, `Upload an image to get its Base64 data URL. Copy it and paste it into HTML, CSS or code.`, ['base64-to-image','image-converter','image-compressor']); const fileEl=t.querySelector('#b64-file'); const out=t.querySelector('#b64-output'); const info=t.querySelector('#b64-info'); const first=t.querySelector('#b64-first'); const preview=t.querySelector('#b64-preview'); fileEl.addEventListener('change', function(){ const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const reader=new FileReader(); reader.onload=function(){ const result=reader.result; out.value=result; info.textContent='File: '+f.name+' — '+(f.size/1024).toFixed(1)+' KB — Base64 length: '+result.length+' characters'; first.textContent='First 200 chars: '+result.slice(0,200)+'…'; preview.src=result; preview.style.display='block'; }; reader.readAsDataURL(f); }); t.querySelector('#b64-copy').addEventListener('click', function(){ if(!out.value){ info.textContent='Please choose an image first.'; return; } copy(out.value); }); }
function base64ToImage(t){ toolShell(t, `<div class="field"><label class="label" for="b64i-input">Base64 string</label><textarea class="textarea" id="b64i-input" rows="6" placeholder="Paste a Base64 string, with or without the data:image/... prefix…"></textarea></div><div class="error" id="b64i-error" style="display:none"></div><div class="actions"><button class="btn primary" id="b64i-btn">Preview Image</button></div><img id="b64i-preview" style="display:none;max-width:100%;height:auto" alt="Decoded preview"><div class="actions"><button class="btn secondary" id="b64i-download" style="display:none">Download PNG</button></div>`, `Paste a Base64 string (with or without the data: prefix) and preview it, then download it as a PNG.`, ['image-to-base64','image-converter','image-resizer']); const input=t.querySelector('#b64i-input'); const preview=t.querySelector('#b64i-preview'); const errEl=t.querySelector('#b64i-error'); const dlBtn=t.querySelector('#b64i-download'); let current=''; function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } t.querySelector('#b64i-btn').addEventListener('click', function(){ hideErr(); let s=input.value.trim(); if(!s){ showErr('Please paste a Base64 string first.'); return; } if(s.indexOf('data:')!==0){ s='data:image/png;base64,'+s; } current=s; preview.style.display='none'; dlBtn.style.display='none'; preview.onerror=function(){ showErr('That Base64 string is not a valid image. Please check it and try again.'); }; preview.onload=function(){ hideErr(); preview.style.display='block'; dlBtn.style.display='inline-block'; }; preview.src=s; }); dlBtn.addEventListener('click', function(){ if(!current){ return; } const a=document.createElement('a'); a.download='image.png'; a.href=current; a.click(); }); }
function memeText(t){ toolShell(t, `<div class="field"><label class="label" for="meme-file">Choose image</label><input class="input" id="meme-file" type="file" accept="image/*"></div><div class="field"><label class="label" for="meme-top">Top text</label><input class="input" id="meme-top" type="text" placeholder="TOP TEXT"></div><div class="field"><label class="label" for="meme-bottom">Bottom text</label><input class="input" id="meme-bottom" type="text" placeholder="BOTTOM TEXT"></div><div class="field"><label class="label" for="meme-size">Font size (px)</label><input class="input" id="meme-size" type="number" min="10" max="200" value="48"></div><div class="error" id="meme-error" style="display:none"></div><div class="actions"><button class="btn primary" id="meme-btn">Add Meme Text</button></div><canvas id="meme-canvas" style="max-width:100%"></canvas><div class="actions"><button class="btn secondary" id="meme-download" style="display:none">Download Meme</button></div>`, `Upload an image, type top and bottom text, and generate a classic meme with bold white text and a black outline.`, ['image-cropper','image-filters','image-converter']); const fileEl=t.querySelector('#meme-file'); const canvas=t.querySelector('#meme-canvas'); const errEl=t.querySelector('#meme-error'); const dlBtn=t.querySelector('#meme-download'); let img=null; function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } fileEl.addEventListener('change', function(){ hideErr(); const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const url=URL.createObjectURL(f); const im=new Image(); im.onload=function(){ img=im; canvas.width=im.naturalWidth; canvas.height=im.naturalHeight; canvas.getContext('2d').drawImage(im,0,0); dlBtn.style.display='inline-block'; }; im.onerror=function(){ showErr('Could not load that image. Please try another file.'); }; im.src=url; }); t.querySelector('#meme-btn').addEventListener('click', function(){ hideErr(); if(!img){ showErr('Please choose an image first.'); return; } let size=parseInt(t.querySelector('#meme-size').value,10); if(isNaN(size)||size<10){ size=48; } if(size>200){ size=200; } canvas.width=img.naturalWidth; canvas.height=img.naturalHeight; const ctx=canvas.getContext('2d'); ctx.drawImage(img,0,0); ctx.textAlign='center'; ctx.textBaseline='top'; ctx.font='bold '+size+'px sans-serif'; ctx.lineWidth=Math.max(2,Math.round(size/10)); ctx.strokeStyle='#000'; ctx.fillStyle='#fff'; function wrap(text){ const words=text.split(/\s+/).filter(Boolean); const lines=[]; let line=''; words.forEach(function(w){ const test=line?line+' '+w:w; if(ctx.measureText(test).width>canvas.width-40 && line){ lines.push(line); line=w; } else { line=test; } }); if(line){ lines.push(line); } return lines; } function drawLines(lines,startY){ lines.forEach(function(line,i){ const x=canvas.width/2; const y=startY+i*(size+6); ctx.strokeText(line,x,y); ctx.fillText(line,x,y); }); } const topLines=wrap((t.querySelector('#meme-top').value||'').toUpperCase()); const bottomLines=wrap((t.querySelector('#meme-bottom').value||'').toUpperCase()); drawLines(topLines,10); const bottomStart=canvas.height-10-bottomLines.length*(size+6); drawLines(bottomLines,Math.max(10,bottomStart)); dlBtn.style.display='inline-block'; }); dlBtn.addEventListener('click', function(){ const a=document.createElement('a'); a.download='meme.png'; a.href=canvas.toDataURL('image/png'); a.click(); }); }
function faviconGen(t){ toolShell(t, `<div class="field"><label class="label" for="fav-file">Choose image</label><input class="input" id="fav-file" type="file" accept="image/*"></div><div class="error" id="fav-error" style="display:none"></div><div class="actions"><button class="btn primary" id="fav-btn">Generate Favicons</button></div><div class="result" id="fav-output"></div>`, `Upload any image (a square logo works best) and generate favicon PNGs at 16×16, 32×32 and 48×48.`, ['image-resizer','image-compressor','image-converter']); const fileEl=t.querySelector('#fav-file'); const errEl=t.querySelector('#fav-error'); const output=t.querySelector('#fav-output'); let img=null; function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } fileEl.addEventListener('change', function(){ hideErr(); const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const url=URL.createObjectURL(f); const im=new Image(); im.onload=function(){ img=im; output.textContent='Image loaded — click Generate Favicons.'; }; im.onerror=function(){ showErr('Could not load that image. Please try another file.'); }; im.src=url; }); t.querySelector('#fav-btn').addEventListener('click', function(){ hideErr(); if(!img){ showErr('Please choose an image first.'); return; } output.innerHTML=''; [16,32,48].forEach(function(size){ const wrap=document.createElement('div'); wrap.className='field'; const label=document.createElement('div'); label.textContent=size+' × '+size; const cv=document.createElement('canvas'); cv.width=size; cv.height=size; cv.style.cssText='max-width:100%;border:1px solid #ddd'; const ctx=cv.getContext('2d'); const side=Math.min(img.naturalWidth,img.naturalHeight); const sx=(img.naturalWidth-side)/2; const sy=(img.naturalHeight-side)/2; ctx.drawImage(img,sx,sy,side,side,0,0,size,size); const btn=document.createElement('button'); btn.className='btn secondary'; btn.textContent='Download favicon-'+size+'.png'; btn.addEventListener('click', function(){ const a=document.createElement('a'); a.download='favicon-'+size+'.png'; a.href=cv.toDataURL('image/png'); a.click(); }); wrap.appendChild(label); wrap.appendChild(cv); wrap.appendChild(document.createElement('br')); wrap.appendChild(btn); output.appendChild(wrap); }); }); }
function imagePalette(t){ toolShell(t, `<div class="field"><label class="label" for="pal-file">Choose image</label><input class="input" id="pal-file" type="file" accept="image/*"></div><div class="error" id="pal-error" style="display:none"></div><canvas id="pal-canvas" style="max-width:100%"></canvas><div class="result" id="pal-output"></div>`, `Upload an image to extract its 6 most dominant colors. Click any swatch to copy its HEX code.`, ['color-palette-generator','hex-to-rgb','image-filters']); const fileEl=t.querySelector('#pal-file'); const canvas=t.querySelector('#pal-canvas'); const errEl=t.querySelector('#pal-error'); const output=t.querySelector('#pal-output'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } function toHex(v){ return v.toString(16).padStart(2,'0'); } fileEl.addEventListener('change', function(){ hideErr(); const f=fileEl.files && fileEl.files[0]; if(!f){ return; } const url=URL.createObjectURL(f); const im=new Image(); im.onload=function(){ const scale=Math.min(1,100/Math.max(im.naturalWidth,im.naturalHeight)); canvas.width=Math.max(1,Math.round(im.naturalWidth*scale)); canvas.height=Math.max(1,Math.round(im.naturalHeight*scale)); const ctx=canvas.getContext('2d'); ctx.drawImage(im,0,0,canvas.width,canvas.height); let data; try{ data=ctx.getImageData(0,0,canvas.width,canvas.height).data; }catch(e){ showErr('This image could not be read (it may be blocked for security). Try another image.'); return; } const counts={}; for(let i=0;i<data.length;i+=16){ const a=data[i+3]; if(a<128){ continue; } const r=Math.min(255,Math.round(data[i]/16)*16); const g=Math.min(255,Math.round(data[i+1]/16)*16); const b=Math.min(255,Math.round(data[i+2]/16)*16); const key=r+','+g+','+b; counts[key]=(counts[key]||0)+1; } const sorted=Object.keys(counts).sort(function(x,y){ return counts[y]-counts[x]; }).slice(0,6); output.innerHTML=''; if(!sorted.length){ output.textContent='No colors found in this image.'; return; } sorted.forEach(function(key){ const parts=key.split(',').map(Number); const hex='#'+toHex(parts[0])+toHex(parts[1])+toHex(parts[2]); const wrap=document.createElement('div'); wrap.className='field'; wrap.style.cursor='pointer'; const sw=document.createElement('div'); sw.style.cssText='width:100%;height:44px;background:'+hex; const label=document.createElement('div'); label.textContent=hex+' — click to copy'; wrap.appendChild(sw); wrap.appendChild(label); wrap.addEventListener('click', function(){ copy(hex); }); output.appendChild(wrap); }); }; im.onerror=function(){ showErr('Could not load that image. Please try another file.'); }; im.src=url; }); }
function hexToRgb(t){ toolShell(t, `<div class="field"><label class="label" for="hex-input">HEX color</label><input class="input" id="hex-input" type="text" placeholder="#FF5733" value="#FF5733"></div><div class="error" id="hex-error" style="display:none"></div><div class="actions"><button class="btn primary" id="hex-btn">Convert to RGB</button></div><div class="result" id="hex-result"></div>`, `Type a HEX color like #FF5733 (or FF5733, or the short form #F53) and convert it to RGB.`, ['rgb-to-hex','color-palette-generator','contrast-checker']); const input=t.querySelector('#hex-input'); const errEl=t.querySelector('#hex-error'); const result=t.querySelector('#hex-result'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; result.innerHTML=''; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } function convert(){ hideErr(); let v=input.value.trim(); if(v.charAt(0)==='#'){ v=v.slice(1); } if(v.length===3){ v=v.split('').map(function(c){ return c+c; }).join(''); } if(!/^[0-9a-fA-F]{6}$/.test(v)){ showErr('Please enter a valid HEX color, e.g. #FF5733 or #F53.'); return; } const r=parseInt(v.slice(0,2),16); const g=parseInt(v.slice(2,4),16); const b=parseInt(v.slice(4,6),16); const rgb='rgb('+r+', '+g+', '+b+')'; result.innerHTML='<div style="width:100%;height:48px;background:'+esc('#'+v.toLowerCase())+'"></div><div class="result-big">'+esc(rgb)+'</div><button class="btn secondary" id="hex-copy">Copy RGB</button>'; const copyBtn=result.querySelector('#hex-copy'); if(copyBtn){ copyBtn.addEventListener('click', function(){ copy(rgb); }); } } t.querySelector('#hex-btn').addEventListener('click', convert); }
function rgbToHex(t){ toolShell(t, `<div class="row" style="display:flex;flex-wrap:wrap;gap:8px"><div class="field"><label class="label" for="rgb-r">R (0–255)</label><input class="input" id="rgb-r" type="number" min="0" max="255" value="255"></div><div class="field"><label class="label" for="rgb-g">G (0–255)</label><input class="input" id="rgb-g" type="number" min="0" max="255" value="87"></div><div class="field"><label class="label" for="rgb-b">B (0–255)</label><input class="input" id="rgb-b" type="number" min="0" max="255" value="51"></div></div><div class="error" id="rgb-error" style="display:none"></div><div class="actions"><button class="btn primary" id="rgb-btn">Convert to HEX</button></div><div class="result" id="rgb-result"></div>`, `Enter red, green and blue values from 0 to 255 and get the HEX color code.`, ['hex-to-rgb','random-color-generator','contrast-checker']); const errEl=t.querySelector('#rgb-error'); const result=t.querySelector('#rgb-result'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; result.innerHTML=''; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } t.querySelector('#rgb-btn').addEventListener('click', function(){ hideErr(); const r=parseInt(t.querySelector('#rgb-r').value,10); const g=parseInt(t.querySelector('#rgb-g').value,10); const b=parseInt(t.querySelector('#rgb-b').value,10); if([r,g,b].some(function(v){ return isNaN(v)||v<0||v>255||!Number.isInteger(v); })){ showErr('Please enter whole numbers from 0 to 255 for R, G and B.'); return; } const hex='#'+[r,g,b].map(function(v){ return v.toString(16).padStart(2,'0'); }).join('').toUpperCase(); result.innerHTML='<div style="width:100%;height:48px;background:'+esc(hex)+'"></div><div class="result-big">'+esc(hex)+'</div><button class="btn secondary" id="rgb-copy">Copy HEX</button>'; const copyBtn=result.querySelector('#rgb-copy'); if(copyBtn){ copyBtn.addEventListener('click', function(){ copy(hex); }); } }); }
function paletteGen(t){ toolShell(t, `<div class="actions"><button class="btn primary" id="cpal-btn">Generate Palette</button></div><div class="result" id="cpal-output"></div>`, `Generate a harmonious 5-color palette. Click any color to copy its HEX code.`, ['hex-to-rgb','rgb-to-hex','random-color-generator']); const output=t.querySelector('#cpal-output'); function hslToHex(h,s,l){ s/=100; l/=100; const c=(1-Math.abs(2*l-1))*s; const x=c*(1-Math.abs(((h/60)%2)-1)); const m=l-c/2; let r=0; let g=0; let b=0; if(h<60){ r=c; g=x; b=0; } else if(h<120){ r=x; g=c; b=0; } else if(h<180){ r=0; g=c; b=x; } else if(h<240){ r=0; g=x; b=c; } else if(h<300){ r=x; g=0; b=c; } else { r=c; g=0; b=x; } return '#'+[r+m,g+m,b+m].map(function(v){ return Math.round(v*255).toString(16).padStart(2,'0'); }).join('').toUpperCase(); } function generate(){ const base=Math.floor(Math.random()*360); const offsets=[-30,-15,0,15,30]; const lights=[55,62,48,58,42]; output.innerHTML=''; offsets.forEach(function(off,i){ const hue=(base+off+360)%360; const hex=hslToHex(hue,65,lights[i]); const wrap=document.createElement('div'); wrap.className='field'; wrap.style.cursor='pointer'; const sw=document.createElement('div'); sw.style.cssText='width:100%;height:48px;background:'+hex; const label=document.createElement('div'); label.textContent=hex+' — click to copy'; wrap.appendChild(sw); wrap.appendChild(label); wrap.addEventListener('click', function(){ copy(hex); }); output.appendChild(wrap); }); } t.querySelector('#cpal-btn').addEventListener('click', generate); generate(); }
function gradientGen(t){ toolShell(t, `<div class="row" style="display:flex;flex-wrap:wrap;gap:8px"><div class="field"><label class="label" for="grad-c1">Color 1</label><input class="input" id="grad-c1" type="color" value="#FF5733"></div><div class="field"><label class="label" for="grad-c2">Color 2</label><input class="input" id="grad-c2" type="color" value="#3357FF"></div><div class="field"><label class="label" for="grad-angle">Angle (<span id="grad-angle-label">90°</span>)</label><input class="input" id="grad-angle" type="range" min="0" max="360" value="90"></div></div><div class="result" id="grad-preview" style="min-height:120px"></div><div class="result" id="grad-code"></div><div class="actions"><button class="btn primary" id="grad-copy">Copy CSS</button></div>`, `Pick two colors and an angle to build a linear gradient. The preview and CSS update live.`, ['color-palette-generator','contrast-checker','hex-to-rgb']); const c1=t.querySelector('#grad-c1'); const c2=t.querySelector('#grad-c2'); const angle=t.querySelector('#grad-angle'); const angleLabel=t.querySelector('#grad-angle-label'); const preview=t.querySelector('#grad-preview'); const codeEl=t.querySelector('#grad-code'); function update(){ const a=angle.value; angleLabel.textContent=a+'°'; const css='background: linear-gradient('+a+'deg, '+c1.value+', '+c2.value+');'; preview.style.background='linear-gradient('+a+'deg, '+c1.value+', '+c2.value+')'; codeEl.textContent=css; } c1.addEventListener('input', update); c2.addEventListener('input', update); angle.addEventListener('input', update); t.querySelector('#grad-copy').addEventListener('click', function(){ copy(codeEl.textContent); }); update(); }
function contrastCheck(t){ toolShell(t, `<div class="row" style="display:flex;flex-wrap:wrap;gap:8px"><div class="field"><label class="label" for="con-c1">Text color</label><input class="input" id="con-c1" type="color" value="#000000"></div><div class="field"><label class="label" for="con-c2">Background color</label><input class="input" id="con-c2" type="color" value="#FFFFFF"></div></div><div class="result" id="con-preview">Sample text — AaBbCc 123</div><div class="result" id="con-result"></div>`, `Pick a text color and a background color to check their WCAG contrast ratio and AA / AAA pass or fail.`, ['hex-to-rgb','rgb-to-hex','gradient-generator']); const c1=t.querySelector('#con-c1'); const c2=t.querySelector('#con-c2'); const result=t.querySelector('#con-result'); const preview=t.querySelector('#con-preview'); function lum(hex){ const r=parseInt(hex.slice(1,3),16)/255; const g=parseInt(hex.slice(3,5),16)/255; const b=parseInt(hex.slice(5,7),16)/255; function lin(c){ return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4); } return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b); } function update(){ const L1=lum(c1.value); const L2=lum(c2.value); const lighter=Math.max(L1,L2); const darker=Math.min(L1,L2); const ratio=(lighter+0.05)/(darker+0.05); preview.style.background=c2.value; preview.style.color=c1.value; function pf(ok){ return ok?'PASS':'FAIL'; } result.innerHTML='<div class="result-big">Contrast ratio: '+ratio.toFixed(2)+' : 1</div><div>AA normal text (≥ 4.5): '+pf(ratio>=4.5)+'</div><div>AA large text (≥ 3): '+pf(ratio>=3)+'</div><div>AAA normal text (≥ 7): '+pf(ratio>=7)+'</div><div>AAA large text (≥ 4.5): '+pf(ratio>=4.5)+'</div>'; } c1.addEventListener('input', update); c2.addEventListener('input', update); update(); }
function randomColorGen(t){ toolShell(t, `<div class="actions"><button class="btn primary" id="rand-btn">Generate Random Color</button></div><div class="result" id="rand-swatch" style="min-height:100px"></div><div class="result"><div class="result-big" id="rand-hex">#000000</div><div id="rand-rgb">rgb(0, 0, 0)</div></div><div class="actions"><button class="btn secondary" id="rand-copy">Copy HEX</button></div><div class="field"><label class="label">History (last 8 — click to copy)</label><div id="rand-history"></div></div>`, `Generate one random color at a time with its HEX and RGB values. Click a history swatch to copy it.`, ['color-palette-generator','hex-to-rgb','gradient-generator']); const swatch=t.querySelector('#rand-swatch'); const hexEl=t.querySelector('#rand-hex'); const rgbEl=t.querySelector('#rand-rgb'); const historyEl=t.querySelector('#rand-history'); const copyBtn=t.querySelector('#rand-copy'); let history=[]; let currentHex='#000000'; function generate(){ const r=Math.floor(Math.random()*256); const g=Math.floor(Math.random()*256); const b=Math.floor(Math.random()*256); const hex='#'+[r,g,b].map(function(v){ return v.toString(16).padStart(2,'0'); }).join('').toUpperCase(); currentHex=hex; swatch.style.background=hex; hexEl.textContent=hex; rgbEl.textContent='rgb('+r+', '+g+', '+b+')'; history.unshift(hex); if(history.length>8){ history.pop(); } historyEl.innerHTML=''; history.forEach(function(h){ const s=document.createElement('div'); s.style.cssText='width:36px;height:36px;display:inline-block;margin:4px;cursor:pointer;background:'+h+';border:1px solid #ddd'; s.title=h; s.addEventListener('click', function(){ copy(h); }); historyEl.appendChild(s); }); } copyBtn.addEventListener('click', function(){ copy(currentHex); }); t.querySelector('#rand-btn').addEventListener('click', generate); generate(); }
function stopwatchTool(t){ window.__toolToken=(window.__toolToken||0)+1;const myToken=window.__toolToken; toolShell(t, `<div class="result"><div class="result-big" id="sw-display">00:00.00</div></div><div class="actions"><button class="btn primary" id="sw-toggle">Start</button><button class="btn secondary" id="sw-lap">Lap</button><button class="btn secondary" id="sw-reset">Reset</button></div><div class="field"><label class="label">Laps</label><ul id="sw-laps" style="max-height:200px;overflow:auto;margin:0;padding-left:20px"></ul></div>`, `Start the stopwatch, tap Lap to record splits, and Reset to clear. Time shows minutes : seconds . centiseconds.`, ['countdown-timer','world-clock','days-between-dates']); const display=t.querySelector('#sw-display'); const toggle=t.querySelector('#sw-toggle'); const lapsEl=t.querySelector('#sw-laps'); let elapsed=0; let startAt=0; let iv=null; let running=false; let laps=[]; let lastLap=0; function fmtTime(ms){ const totalCs=Math.floor(ms/10); const cs=totalCs%100; const totalSec=Math.floor(totalCs/100); const s=totalSec%60; const m=Math.floor(totalSec/60); return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+String(cs).padStart(2,'0'); } toggle.addEventListener('click', function(){ if(running){ elapsed=Date.now()-startAt; if(iv){ clearInterval(iv); iv=null; } running=false; toggle.textContent='Start'; } else { startAt=Date.now()-elapsed; iv=setInterval(function(){ if(myToken!==window.__toolToken){ clearInterval(iv); return; } elapsed=Date.now()-startAt; display.textContent=fmtTime(elapsed); },31); running=true; toggle.textContent='Stop'; } }); t.querySelector('#sw-lap').addEventListener('click', function(){ if(!running && elapsed===0){ return; } const lapTime=elapsed-lastLap; lastLap=elapsed; const n=laps.length+1; laps.push(n); const li=document.createElement('li'); li.textContent='Lap '+n+': '+fmtTime(lapTime)+' (total '+fmtTime(elapsed)+')'; lapsEl.appendChild(li); }); t.querySelector('#sw-reset').addEventListener('click', function(){ if(iv){ clearInterval(iv); iv=null; } running=false; elapsed=0; lastLap=0; laps=[]; toggle.textContent='Start'; display.textContent='00:00.00'; lapsEl.innerHTML=''; }); }
function countdownTool(t){ window.__toolToken=(window.__toolToken||0)+1;const myToken=window.__toolToken; toolShell(t, `<div class="row" style="display:flex;flex-wrap:wrap;gap:8px"><div class="field"><label class="label" for="cd-min">Minutes (0–999)</label><input class="input" id="cd-min" type="number" min="0" max="999" value="5"></div><div class="field"><label class="label" for="cd-sec">Seconds (0–59)</label><input class="input" id="cd-sec" type="number" min="0" max="59" value="0"></div></div><div class="error" id="cd-error" style="display:none"></div><div class="result"><div class="result-big" id="cd-display">05:00</div><div id="cd-msg"></div></div><div class="actions"><button class="btn primary" id="cd-start">Start</button><button class="btn secondary" id="cd-pause">Pause</button><button class="btn secondary" id="cd-reset">Reset</button></div>`, `Enter minutes and seconds, then Start. Pause to hold the countdown, Reset to clear it. A beep sounds when time is up.`, ['stopwatch','world-clock','days-until-date']); const minEl=t.querySelector('#cd-min'); const secEl=t.querySelector('#cd-sec'); const display=t.querySelector('#cd-display'); const msgEl=t.querySelector('#cd-msg'); const errEl=t.querySelector('#cd-error'); let remainingMs=0; let endAt=0; let iv=null; let running=false; function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } function show(ms){ const totalSec=Math.max(0,Math.ceil(ms/1000)); const m=Math.floor(totalSec/60); const s=totalSec%60; display.textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0'); } function beep(){ try{ const AC=window.AudioContext||window.webkitAudioContext; if(!AC){ return; } const ac=new AC(); const o=ac.createOscillator(); const g=ac.createGain(); o.connect(g); g.connect(ac.destination); o.frequency.value=880; o.start(); o.stop(ac.currentTime+0.3); }catch(e){} } t.querySelector('#cd-start').addEventListener('click', function(){ hideErr(); if(running){ return; } if(remainingMs<=0){ const mins=parseInt(minEl.value,10); const secs=parseInt(secEl.value,10); if(isNaN(mins)||isNaN(secs)||mins<0||mins>999||secs<0||secs>59){ showErr('Please enter minutes 0–999 and seconds 0–59.'); return; } const total=(mins*60+secs)*1000; if(total<=0){ showErr('Please enter a countdown longer than 0 seconds.'); return; } remainingMs=total; } msgEl.textContent=''; endAt=Date.now()+remainingMs; running=true; show(remainingMs); iv=setInterval(function(){ if(myToken!==window.__toolToken){ clearInterval(iv); return; } remainingMs=endAt-Date.now(); if(remainingMs<=0){ clearInterval(iv); iv=null; running=false; remainingMs=0; show(0); msgEl.textContent="Time's up!"; beep(); return; } show(remainingMs); },200); }); t.querySelector('#cd-pause').addEventListener('click', function(){ if(!running){ return; } if(iv){ clearInterval(iv); iv=null; } running=false; remainingMs=endAt-Date.now(); if(remainingMs<0){ remainingMs=0; } show(remainingMs); }); t.querySelector('#cd-reset').addEventListener('click', function(){ if(iv){ clearInterval(iv); iv=null; } running=false; remainingMs=0; msgEl.textContent=''; hideErr(); show(0); }); show(5*60*1000); }
function worldClock(t){ window.__toolToken=(window.__toolToken||0)+1;const myToken=window.__toolToken; toolShell(t, `<div class="result" id="wc-output"></div>`, `Live clocks for six time zones, updating every second.`, ['time-zone-converter','stopwatch','countdown-timer']); const output=t.querySelector('#wc-output'); const zones=[{label:'UTC',tz:'UTC'},{label:'Karachi (PKT)',tz:'Asia/Karachi'},{label:'New York (EST)',tz:'America/New_York'},{label:'London (GMT)',tz:'Europe/London'},{label:'Delhi (IST)',tz:'Asia/Kolkata'},{label:'Tokyo (JST)',tz:'Asia/Tokyo'}]; function tick(){ const now=new Date(); output.innerHTML='<div class="metric-grid">'+zones.map(function(z){ let txt='Unavailable'; try{ txt=new Intl.DateTimeFormat('en-GB',{timeZone:z.tz,weekday:'short',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now); }catch(e){} return '<div><strong>'+esc(z.label)+'</strong><div>'+esc(txt)+'</div></div>'; }).join('')+'</div>'; } tick(); const iv=setInterval(function(){ if(myToken!==window.__toolToken){ clearInterval(iv); return; } tick(); },1000); }
function daysBetween(t){ toolShell(t, `<div class="field"><label class="label" for="db-d1">First date</label><input class="input" id="db-d1" type="date"></div><div class="field"><label class="label" for="db-d2">Second date</label><input class="input" id="db-d2" type="date"></div><div class="error" id="db-error" style="display:none"></div><div class="actions"><button class="btn primary" id="db-btn">Count Days</button></div><div class="result" id="db-result"></div>`, `Pick two dates to count the exact days between them, with a weeks + days breakdown and an inclusive count.`, ['days-until-date','age-calculator','world-clock']); const errEl=t.querySelector('#db-error'); const result=t.querySelector('#db-result'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; result.innerHTML=''; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } function toUTC(val){ const parts=val.split('-').map(Number); return Date.UTC(parts[0],parts[1]-1,parts[2]); } t.querySelector('#db-btn').addEventListener('click', function(){ hideErr(); const v1=t.querySelector('#db-d1').value; const v2=t.querySelector('#db-d2').value; if(!v1||!v2){ showErr('Please pick both dates.'); return; } const diff=Math.abs(Math.round((toUTC(v2)-toUTC(v1))/86400000)); const weeks=Math.floor(diff/7); const rem=diff%7; result.innerHTML='<div class="result-big">'+diff+' day(s)</div><div>'+weeks+' week(s) + '+rem+' day(s)</div><div>Inclusive count: '+(diff+1)+' day(s)</div>'; }); }
function daysUntil(t){ toolShell(t, `<div class="field"><label class="label" for="du-date">Target date</label><input class="input" id="du-date" type="date"></div><div class="error" id="du-error" style="display:none"></div><div class="actions"><button class="btn primary" id="du-btn">How Many Days?</button></div><div class="result" id="du-result"></div>`, `Pick any date to see how many days are left until it — or how many days have passed since it.`, ['days-between-dates','age-calculator','countdown-timer']); const errEl=t.querySelector('#du-error'); const result=t.querySelector('#du-result'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; result.innerHTML=''; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } t.querySelector('#du-btn').addEventListener('click', function(){ hideErr(); const v=t.querySelector('#du-date').value; if(!v){ showErr('Please pick a date.'); return; } const parts=v.split('-').map(Number); const targetUTC=Date.UTC(parts[0],parts[1]-1,parts[2]); const now=new Date(); const todayUTC=Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()); const diff=Math.round((targetUTC-todayUTC)/86400000); const weekday=new Date(targetUTC).toLocaleDateString('en-GB',{weekday:'long',timeZone:'UTC'}); let main=''; if(diff>0){ main=diff+' day(s) to go'; } else if(diff<0){ main=Math.abs(diff)+' day(s) ago'; } else { main='Today!'; } result.innerHTML='<div class="result-big">'+esc(main)+'</div><div>That date falls on a '+esc(weekday)+'</div>'; }); }
function tzConvert(t){ toolShell(t, `<div class="field"><label class="label" for="tz-datetime">Date & time</label><input class="input" id="tz-datetime" type="datetime-local"></div><div class="row" style="display:flex;flex-wrap:wrap;gap:8px"><div class="field"><label class="label" for="tz-from">From zone</label><select class="select" id="tz-from"><option value="Local">Local</option><option value="UTC">UTC</option><option value="Asia/Karachi">Asia/Karachi</option><option value="America/New_York">America/New_York</option><option value="Europe/London">Europe/London</option><option value="Asia/Kolkata">Asia/Kolkata</option><option value="Asia/Tokyo">Asia/Tokyo</option><option value="Australia/Sydney">Australia/Sydney</option></select></div><div class="field"><label class="label" for="tz-to">To zone</label><select class="select" id="tz-to"><option value="Local">Local</option><option value="UTC">UTC</option><option value="Asia/Karachi">Asia/Karachi</option><option value="America/New_York">America/New_York</option><option value="Europe/London">Europe/London</option><option value="Asia/Kolkata">Asia/Kolkata</option><option value="Asia/Tokyo">Asia/Tokyo</option><option value="Australia/Sydney">Australia/Sydney</option></select></div></div><div class="error" id="tz-error" style="display:none"></div><div class="actions"><button class="btn primary" id="tz-btn">Convert</button></div><div class="result" id="tz-result"></div>`, `Enter a date and time in one time zone and convert it to another. Daylight saving is handled by the Intl API.`, ['world-clock','days-between-dates','days-until-date']); const errEl=t.querySelector('#tz-error'); const result=t.querySelector('#tz-result'); function showErr(msg){ errEl.textContent=msg; errEl.style.display='block'; result.innerHTML=''; } function hideErr(){ errEl.textContent=''; errEl.style.display='none'; } function resolveZone(z){ return z==='Local'?Intl.DateTimeFormat().resolvedOptions().timeZone:z; } function getOffset(date,zone){ const tz=resolveZone(zone); const dtf=new Intl.DateTimeFormat('en-US',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}); const parts={}; dtf.formatToParts(date).forEach(function(p){ if(p.type!=='literal'){ parts[p.type]=p.value; } }); let h=parseInt(parts.hour,10); if(h===24){ h=0; } const asUTC=Date.UTC(parseInt(parts.year,10),parseInt(parts.month,10)-1,parseInt(parts.day,10),h,parseInt(parts.minute,10),parseInt(parts.second,10)); return asUTC-Math.floor(date.getTime()/1000)*1000; } t.querySelector('#tz-btn').addEventListener('click', function(){ hideErr(); const v=t.querySelector('#tz-datetime').value; if(!v){ showErr('Please pick a date and time.'); return; } const fromZone=t.querySelector('#tz-from').value; const toZone=t.querySelector('#tz-to').value; const split=v.split('T'); if(split.length!==2){ showErr('Please pick a valid date and time.'); return; } const dParts=split[0].split('-').map(Number); const tParts=split[1].split(':').map(Number); if(dParts.length!==3||tParts.length<2||dParts.some(isNaN)||tParts.some(isNaN)){ showErr('Please pick a valid date and time.'); return; } const inputAsUTC=Date.UTC(dParts[0],dParts[1]-1,dParts[2],tParts[0],tParts[1],0); const offFrom=getOffset(new Date(inputAsUTC),fromZone); const trueUTC=inputAsUTC-offFrom; const offTo=getOffset(new Date(trueUTC),toZone); const targetMs=trueUTC+offTo; const td=new Date(targetMs); function pad(n){ return String(n).padStart(2,'0'); } const out=td.getUTCFullYear()+'-'+pad(td.getUTCMonth()+1)+'-'+pad(td.getUTCDate())+' '+pad(td.getUTCHours())+':'+pad(td.getUTCMinutes())+' ('+resolveZone(toZone)+')'; result.innerHTML='<div class="result-big">'+esc(out)+'</div>'; }); }

