function sciCalc(t){ toolShell(t, `<div class="result-big" id="scientific-calculator-expr" tabindex="0">0</div><div class="result" id="scientific-calculator-res">Result will appear here.</div><div class="error" id="scientific-calculator-err" style="display:none"></div><div class="row" id="scientific-calculator-grid"><button class="btn secondary" data-k="C">C</button><button class="btn secondary" data-k="BACK">Backspace</button><button class="btn secondary" data-k="%">%</button><button class="btn secondary" data-k="÷">÷</button><button class="btn secondary" data-k="7">7</button><button class="btn secondary" data-k="8">8</button><button class="btn secondary" data-k="9">9</button><button class="btn secondary" data-k="×">×</button><button class="btn secondary" data-k="4">4</button><button class="btn secondary" data-k="5">5</button><button class="btn secondary" data-k="6">6</button><button class="btn secondary" data-k="-">-</button><button class="btn secondary" data-k="1">1</button><button class="btn secondary" data-k="2">2</button><button class="btn secondary" data-k="3">3</button><button class="btn secondary" data-k="+">+</button><button class="btn secondary" data-k="√">√</button><button class="btn secondary" data-k="0">0</button><button class="btn secondary" data-k=".">.</button><button class="btn secondary" data-k="^">^</button><button class="btn secondary" data-k="(">(</button><button class="btn secondary" data-k=")">)</button><button class="btn primary" data-k="=">=</button></div>`, `Click the buttons or type on your keyboard (digits, + - * / % ^ ( ), Enter for =, Backspace to delete, Escape to clear).`, ['percentage-calculator','average-calculator','fraction-calculator']);
var expr='';
var exprEl=$('#scientific-calculator-expr');
var resEl=$('#scientific-calculator-res');
var errEl=$('#scientific-calculator-err');
function showErr(m){ errEl.textContent=m; errEl.style.display='block'; }
function clearErr(){ errEl.textContent=''; errEl.style.display='none'; }
function render(){ exprEl.textContent=expr||'0'; }
function formatResult(v){ if(!isFinite(v)) throw new Error('Result is not a finite number.'); var r=Math.round(v*100000000)/100000000; return String(r); }
function parseAndEval(s){
var tokens=[]; var i=0;
while(i<s.length){
var c=s[i];
if(c===' '||c==='\t'||c==='\n'){ i++; continue; }
if((c>='0'&&c<='9')||c==='.'){
var numStr=''; var dotSeen=false;
while(i<s.length&&((s[i]>='0'&&s[i]<='9')||s[i]==='.')){
if(s[i]==='.'){ if(dotSeen) throw new Error('Invalid number: too many decimal points.'); dotSeen=true; }
numStr+=s[i]; i++;
}
if(numStr==='.'||numStr==='') throw new Error('Invalid number.');
var v=parseFloat(numStr); if(isNaN(v)) throw new Error('Invalid number: '+numStr);
tokens.push({type:'num',value:v}); continue;
}
if('+-*/%^()√×÷'.indexOf(c)!==-1){ tokens.push({type:'op',value:c}); i++; continue; }
throw new Error('Invalid character: '+c);
}
if(tokens.length===0) throw new Error('Enter an expression first.');
var pos=0;
function peekTok(){ return tokens[pos]; }
function peekType(){ var tk=tokens[pos]; return tk?tk.type:null; }
function peekVal(){ var tk=tokens[pos]; return tk?tk.value:null; }
function peekNextVal(){ var tk=tokens[pos+1]; return tk?tk.value:null; }
function isFactorStartAt(idx){ var tk=tokens[idx]; if(!tk) return false; if(tk.type==='num') return true; if(tk.type==='op'&&(tk.value==='('||tk.value==='√'||tk.value==='-'||tk.value==='+')) return true; return false; }
function consume(){ return tokens[pos++]; }
function parseExpression(){
var left=parseTerm();
while(peekVal()==='+'||peekVal()==='-'){ var op=consume().value; var right=parseTerm(); if(op==='+') left=left+right; else left=left-right; }
return left;
}
function parseTerm(){
var left=parseFactor();
while(true){
var v=peekVal();
if(v==='*'||v==='×'){ consume(); var r1=parseFactor(); left=left*r1; }
else if(v==='/'||v==='÷'){ consume(); var r2=parseFactor(); if(r2===0) throw new Error('Cannot divide by zero.'); left=left/r2; }
else if(v==='%'){
if(isFactorStartAt(pos+1)){ consume(); var r3=parseFactor(); if(r3===0) throw new Error('Cannot divide by zero.'); left=left%r3; } else break;
}
else if(peekType()==='num'||v==='('||v==='√'){ var r4=parseFactor(); left=left*r4; }
else break;
}
return left;
}
function parseFactor(){
var left=parseUnary();
if(peekVal()==='^'){ consume(); var e=parseFactor(); left=Math.pow(left,e); }
return left;
}
function parseUnary(){
if(peekVal()==='-'){ consume(); return -parseUnary(); }
if(peekVal()==='+'){ consume(); return parseUnary(); }
return parsePostfix();
}
function parsePostfix(){
var val=parsePrimary();
while(peekVal()==='%'){
var nxt=peekNextVal();
if(nxt===null||nxt==='+'||nxt==='-'||nxt==='*'||nxt==='×'||nxt==='/'||nxt==='÷'||nxt==='^'||nxt===')'||nxt==='%'){ consume(); val=val/100; } else break;
}
return val;
}
function parsePrimary(){
var tk=peekTok();
if(!tk) throw new Error('Unexpected end of expression.');
if(tk.type==='num'){ consume(); return tk.value; }
if(tk.type==='op'&&tk.value==='('){ consume(); var v=parseExpression(); if(peekVal()!==')') throw new Error('Mismatched parentheses — missing ).'); consume(); return v; }
if(tk.type==='op'&&tk.value==='√'){ consume(); var inner=parsePrimary(); if(inner<0) throw new Error('Cannot take the square root of a negative number.'); return Math.sqrt(inner); }
throw new Error('Unexpected token: '+String(tk.value));
}
var result=parseExpression();
if(pos<tokens.length) throw new Error('Unexpected token: '+String(tokens[pos].value));
return result;
}
function evaluate(){
if(!expr.trim()){ showErr('Enter an expression first.'); return; }
try{ var val=parseAndEval(expr); resEl.textContent='= '+formatResult(val); clearErr(); }
catch(e){ showErr(e.message||'Invalid expression.'); }
}
$$('#scientific-calculator-grid button').forEach(function(btn){
btn.addEventListener('click',function(){
var k=btn.getAttribute('data-k');
if(k==='C'){ expr=''; resEl.textContent='Result will appear here.'; clearErr(); render(); }
else if(k==='BACK'){ expr=expr.slice(0,-1); render(); }
else if(k==='='){ evaluate(); }
else { expr+=k; render(); clearErr(); }
});
});
exprEl.addEventListener('keydown',function(e){
if(e.key==='Enter'||e.key==='='){ e.preventDefault(); evaluate(); return; }
if(e.key==='Backspace'){ e.preventDefault(); expr=expr.slice(0,-1); render(); return; }
if(e.key==='Escape'){ e.preventDefault(); expr=''; render(); resEl.textContent='Result will appear here.'; clearErr(); return; }
if(/^[0-9.]$/.test(e.key)){ expr+=e.key; render(); clearErr(); return; }
if(e.key==='+'||e.key==='-'||e.key==='%'||e.key==='^'||e.key==='('||e.key===')'){ expr+=e.key; render(); clearErr(); return; }
if(e.key==='*'){ expr+='×'; render(); clearErr(); return; }
if(e.key==='/'){ e.preventDefault(); expr+='÷'; render(); clearErr(); return; }
});
render();
}
function fractionCalc(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="fraction-calculator-n1">Numerator 1</label><input class="input" id="fraction-calculator-n1" type="number" placeholder="e.g. 1"></div><div class="field"><label class="label" for="fraction-calculator-d1">Denominator 1</label><input class="input" id="fraction-calculator-d1" type="number" placeholder="e.g. 2"></div></div><div class="field"><label class="label" for="fraction-calculator-op">Operation</label><select class="select" id="fraction-calculator-op"><option value="+">+ Add</option><option value="-">- Subtract</option><option value="*">× Multiply</option><option value="/">÷ Divide</option></select></div><div class="row"><div class="field"><label class="label" for="fraction-calculator-n2">Numerator 2</label><input class="input" id="fraction-calculator-n2" type="number" placeholder="e.g. 1"></div><div class="field"><label class="label" for="fraction-calculator-d2">Denominator 2</label><input class="input" id="fraction-calculator-d2" type="number" placeholder="e.g. 3"></div></div><div class="actions"><button class="btn primary" id="fraction-calculator-btn">Calculate</button></div><div class="error" id="fraction-calculator-err" style="display:none"></div><div class="result" id="fraction-calculator-out" style="display:none"></div>`, `Enter two fractions and pick an operation.`, ['scientific-calculator','percentage-calculator','average-calculator']);
var errEl=$('#fraction-calculator-err');
var outEl=$('#fraction-calculator-out');
function showErr(m){ errEl.textContent=m; errEl.style.display='block'; outEl.style.display='none'; }
function clearErr(){ errEl.textContent=''; errEl.style.display='none'; }
function gcd(a,b){ a=Math.abs(a); b=Math.abs(b); while(b){ var tmp=a%b; a=b; b=tmp; } return a||1; }
$('#fraction-calculator-btn').addEventListener('click',function(){
var n1Raw=$('#fraction-calculator-n1').value.trim();
var d1Raw=$('#fraction-calculator-d1').value.trim();
var n2Raw=$('#fraction-calculator-n2').value.trim();
var d2Raw=$('#fraction-calculator-d2').value.trim();
if(n1Raw===''||d1Raw===''||n2Raw===''||d2Raw===''){ showErr('Enter all four numbers.'); return; }
var n1=Number(n1Raw); var d1=Number(d1Raw); var n2=Number(n2Raw); var d2=Number(d2Raw);
if(!Number.isInteger(n1)||!Number.isInteger(d1)||!Number.isInteger(n2)||!Number.isInteger(d2)){ showErr('Fractions must use whole numbers.'); return; }
if(d1===0||d2===0){ showErr('Denominator cannot be zero.'); return; }
var op=$('#fraction-calculator-op').value;
var rn; var rd;
if(op==='+'){ rn=n1*d2+n2*d1; rd=d1*d2; }
else if(op==='-'){ rn=n1*d2-n2*d1; rd=d1*d2; }
else if(op==='*'){ rn=n1*n2; rd=d1*d2; }
else { if(n2===0){ showErr('Cannot divide by zero fraction.'); return; } rn=n1*d2; rd=d1*n2; }
if(rd<0){ rn=-rn; rd=-rd; }
var g=gcd(rn,rd); rn=rn/g; rd=rd/g;
var dec=rn/rd;
var decStr=String(Math.round(dec*10000)/10000);
var html='';
if(rd===1){ html='Simplified: <strong>'+rn+'</strong><br>Decimal: <strong>'+decStr+'</strong>'; }
else{
html='Simplified: <strong>'+rn+'/'+rd+'</strong><br>Decimal: <strong>'+decStr+'</strong>';
if(Math.abs(rn)>rd){ var whole=Math.trunc(rn/rd); var rem=Math.abs(rn%rd); if(rem!==0){ html+='<br>Mixed number: <strong>'+whole+' '+rem+'/'+rd+'</strong>'; } }
}
outEl.innerHTML=html; outEl.style.display='block'; clearErr();
});
}
function primeCheck(t){ toolShell(t, `<div class="field"><label class="label" for="prime-checker-input">Number (0 to 1,000,000,000,000)</label><input class="input" id="prime-checker-input" type="number" placeholder="e.g. 97"></div><div class="actions"><button class="btn primary" id="prime-checker-btn">Check</button></div><div class="error" id="prime-checker-err" style="display:none"></div><div class="result" id="prime-checker-out" style="display:none"></div>`, `Enter a whole number to test for primality.`, ['scientific-calculator','factorial-calculator','average-calculator']);
var errEl=$('#prime-checker-err');
var outEl=$('#prime-checker-out');
function showErr(m){ errEl.textContent=m; errEl.style.display='block'; outEl.style.display='none'; }
function clearErr(){ errEl.textContent=''; errEl.style.display='none'; }
function isPrimeSmall(n){ if(n<2) return false; if(n===2||n===3) return true; if(n%2===0||n%3===0) return false; for(var i=5;i*i<=n;i+=6){ if(n%i===0||n%(i+2)===0) return false; } return true; }
function smallestFactor(n){ if(n<2) return null; if(n%2===0) return n===2?null:2; if(n%3===0) return n===3?null:3; for(var i=5;i*i<=n;i+=6){ if(n%i===0) return i; if(n%(i+2)===0) return i+2; } return null; }
function findPrev(n){ for(var d=n-1,steps=0;d>=2&&steps<100000;d--,steps++){ if(isPrimeSmall(d)) return d; } return null; }
function findNext(n){ for(var u=n+1,steps2=0;steps2<100000;u++,steps2++){ if(isPrimeSmall(u)) return u; } return null; }
$('#prime-checker-btn').addEventListener('click',function(){
var raw=$('#prime-checker-input').value.trim();
if(raw===''){ showErr('Enter a number.'); return; }
var n=Number(raw);
if(!Number.isInteger(n)||n<0||n>1000000000000){ showErr('Enter a whole number from 0 to 1,000,000,000,000.'); return; }
if(n<2){
outEl.innerHTML='<strong>'+n+'</strong> is <strong>not prime</strong>.<br>Previous prime: None<br>Next prime: <strong>2</strong>';
outEl.style.display='block'; clearErr(); return;
}
var factor=smallestFactor(n);
var prev=findPrev(n);
var next=findNext(n);
var prevStr=prev===null?'None found within 100,000 steps':'<strong>'+prev+'</strong>';
var nextStr=next===null?'Not found within 100,000 steps':'<strong>'+next+'</strong>';
var html='';
if(factor===null){ html='<strong>'+n+'</strong> is <strong>prime</strong>.<br>Previous prime: '+prevStr+'<br>Next prime: '+nextStr; }
else { html='<strong>'+n+'</strong> is <strong>not prime</strong>.<br>Smallest factor: <strong>'+factor+'</strong> ('+n+' = '+factor+' × '+(n/factor)+')<br>Previous prime: '+prevStr+'<br>Next prime: '+nextStr; }
outEl.innerHTML=html; outEl.style.display='block'; clearErr();
});
}
