if(raw===''){ showErr('Enter at least one number.'); return; }
var tokens=raw.split(/[\s,;]+/).filter(function(x){ return x!==''; });
var nums=[];
for(var i=0;i<tokens.length;i++){ var v=Number(tokens[i]); if(isNaN(v)){ showErr('Invalid number: '+tokens[i]+'. Use numbers only.'); return; } nums.push(v); }
if(nums.length===0){ showErr('Enter at least one number.'); return; }
var count=nums.length;
