var mean=sum/count;
var sorted=nums.slice().sort(function(a,b){ return a-b; });
var median;
if(count%2===1){ median=sorted[(count-1)/2]; } else { median=(sorted[count/2-1]+sorted[count/2])/2; }
var freq={}; var maxFreq=0;
for(var f=0;f<nums.length;f++){ var key=String(nums[f]); freq[key]=(freq[key]||0)+1; if(freq[key]>maxFreq) maxFreq=freq[key]; }
var distinct=Object.keys(freq).length;
var modeStr;
if(maxFreq===1&&distinct>1){ modeStr='No mode (all values appear once)'; }
else { var modes=[]; for(var k in freq){ if(freq[k]===maxFreq) modes.push(Number(k)); } modes.sort(function(a,b){ return a-b; }); modeStr=modes.map(fmt4).join(', '); }
var min=sorted[0]; var max=sorted[sorted.length-1]; var range=max-min;
var html='Count: <strong>'+count+'</strong><br>Mean: <strong>'+fmt4(mean)+'</strong><br>Median: <strong>'+fmt4(median)+'</strong><br>Mode: <strong>'+modeStr+'</strong><br>Min: <strong>'+fmt4(min)+'</strong><br>Max: <strong>'+fmt4(max)+'</strong><br>Range: <strong>'+fmt4(range)+'</strong>';
