function tiktokHookGen(t){ toolShell(t, `<div class="field"><label class="label" for="th-idea">Video idea</label><input class="input" id="th-idea" type="text" placeholder="e.g. my morning routine, a budget travel hack"></div><div class="field"><label class="label" for="th-niche">Niche</label><input class="input" id="th-niche" type="text" placeholder="e.g. fitness, cooking, study tips"></div><div class="error" id="th-err" style="display:none"></div><div class="actions"><button class="btn primary" id="th-btn">Generate hooks</button></div><div id="th-out"></div>`, `Enter your video idea and niche to get 5 scroll-stopping hooks. Copy any hook to open your video with it.`, ['ai-caption-generator','ai-hashtag-generator','post-idea-generator','youtube-title-generator']); const out=$('#th-out'),err=$('#th-err'); let items=[]; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} out.addEventListener('click',e=>{const b=e.target.closest('[data-copy]');if(!b)return;copy(items[+b.dataset.copy]);}); $('#th-btn').addEventListener('click',()=>{hideErr();const idea=$('#th-idea').value.trim(),niche=$('#th-niche').value.trim();if(!idea||!niche){showErr('Please enter both a video idea and a niche.');return;}items=['Stop scrolling if you care about '+niche+'.','POV: You finally try '+idea+' — and it actually works.','Nobody talks about this '+niche+' trick: '+idea+'.','I tried '+idea+' so you do not have to. Here is what happened.','Watch till the end — the last tip about '+idea+' is the one that changes everything.'];out.innerHTML=items.map((s,i)=>'<div class="result"><div>'+esc(s)+'</div><div class="actions"><button class="btn secondary" data-copy="'+i+'">Copy</button></div></div>').join('');}); }
function postIdeaGen(t){ toolShell(t, `<div class="field"><label class="label" for="pi-niche">Niche</label><input class="input" id="pi-niche" type="text" placeholder="e.g. fitness, personal finance"></div><div class="field"><label class="label" for="pi-platform">Platform</label><select class="select" id="pi-platform"><option value="Instagram">Instagram</option><option value="TikTok">TikTok</option><option value="YouTube">YouTube</option><option value="Facebook">Facebook</option><option value="LinkedIn">LinkedIn</option></select></div><div class="error" id="pi-err" style="display:none"></div><div class="actions"><button class="btn primary" id="pi-btn">Generate ideas</button><button class="btn secondary" id="pi-copy">Copy all</button></div><div id="pi-out"></div>`, `Enter your niche and platform to get 7 content ideas, each with a one-line angle.`, ['content-calendar-generator','tiktok-hook-generator','youtube-title-generator','ai-caption-generator']); const out=$('#pi-out'),err=$('#pi-err'); let items=[]; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} $('#pi-btn').addEventListener('click',()=>{hideErr();const niche=$('#pi-niche').value.trim(),platform=$('#pi-platform').value;if(!niche){showErr('Please enter a niche.');return;}items=[{t:'Beginner tutorial: '+niche+' from zero',a:'Angle: make the first step feel easy and doable.'},{t:'5 mistakes beginners make in '+niche,a:'Angle: save your audience from the errors you made.'},{t:'A day in my life working in '+niche,a:'Angle: behind-the-scenes content builds trust fast.'},{t:'Myth vs fact in '+niche,a:'Angle: bust one popular myth and prove it.'},{t:'The tools I use for '+niche,a:'Angle: a practical list your audience can copy today.'},{t:'Answering your most asked '+niche+' questions',a:'Angle: turn audience questions into easy content.'},{t:'My '+niche+' story: how I started',a:'Angle: personal stories get the most saves and shares.'}];out.innerHTML='<p>Ideas for '+esc(platform)+' — '+esc(niche)+'</p>'+items.map((x,i)=>'<div class="result"><div><strong>'+(i+1)+'. '+esc(x.t)+'</strong></div><div>'+esc(x.a)+'</div></div>').join('');}); $('#pi-copy').addEventListener('click',()=>{if(!items.length){toast('Nothing to copy yet.');return;}copy(items.map((x,i)=>(i+1)+'. '+x.t+' — '+x.a).join('\n'));}); }
function calendarGen(t){ toolShell(t, `<div class="field"><label class="label" for="cc-niche">Niche</label><input class="input" id="cc-niche" type="text" placeholder="e.g. fitness, personal finance"></div><div class="field"><label class="label" for="cc-weeks">Weeks</label><select class="select" id="cc-weeks"><option value="1">1 week</option><option value="2">2 weeks</option><option value="3">3 weeks</option><option value="4">4 weeks</option></select></div><div class="error" id="cc-err" style="display:none"></div><div class="actions"><button class="btn primary" id="cc-btn">Generate calendar</button><button class="btn secondary" id="cc-copy">Copy</button><button class="btn secondary" id="cc-dl">Download .txt</button></div><div id="cc-out"></div>`, `Enter your niche and how many weeks you want. You get a day-by-day calendar with a post type and idea for every day.`, ['post-idea-generator','tiktok-hook-generator','ai-caption-generator','ai-hashtag-generator']); const out=$('#cc-out'),err=$('#cc-err'); let text=''; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']; $('#cc-btn').addEventListener('click',()=>{hideErr();const niche=$('#cc-niche').value.trim(),weeks=parseInt($('#cc-weeks').value,10);if(!niche){showErr('Please enter a niche.');return;}const ideas={Reel:'Quick '+niche+' tip in under 60 seconds',Carousel:'5 '+niche+' mistakes to avoid (swipe through)',Story:'Behind the scenes of my '+niche+' work','Short video':niche+' in 30 seconds — part 1','Long video':'Deep dive: everything about '+niche,'Poll / Q&A':'Poll: what '+niche+' topic should I cover next?',Live:'Live Q&A: ask me anything about '+niche};const lines=[];let html='';for(let w=1;w<=weeks;w++){html+='<h3>Week '+w+'</h3><table style="width:100%;border-collapse:collapse;margin-bottom:16px"><tr><th style="text-align:left;border:1px solid #ccc;padding:6px">Day</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Post type</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Idea</th></tr>';days.forEach((d,di)=>{const type=Object.keys(ideas)[(di+(w-1))%7];const idea=ideas[type];html+='<tr><td style="border:1px solid #ccc;padding:6px">'+esc(d)+'</td><td style="border:1px solid #ccc;padding:6px">'+esc(type)+'</td><td style="border:1px solid #ccc;padding:6px">'+esc(idea)+'</td></tr>';lines.push('Week '+w+' — '+d+' | '+type+' | '+idea);});html+='</table>';}text='Content calendar — '+niche+'\n'+lines.join('\n');out.innerHTML=html;}); $('#cc-copy').addEventListener('click',()=>copy(text)); $('#cc-dl').addEventListener('click',()=>downloadText(text,'content-calendar.txt')); }
function citationGen(t){ toolShell(t, `<div class="field"><label class="label" for="ci-author">Author</label><input class="input" id="ci-author" type="text" placeholder="e.g. Smith, J."></div><div class="field"><label class="label" for="ci-title">Title</label><input class="input" id="ci-title" type="text" placeholder="e.g. How to Study Better"></div><div class="row"><div class="field"><label class="label" for="ci-year">Year</label><input class="input" id="ci-year" type="number" placeholder="e.g. 2024"></div><div class="field"><label class="label" for="ci-source">Source</label><input class="input" id="ci-source" type="text" placeholder="e.g. Journal of Learning"></div></div><div class="field"><label class="label" for="ci-style">Style</label><select class="select" id="ci-style"><option value="APA">APA</option><option value="MLA">MLA</option></select></div><div class="error" id="ci-err" style="display:none"></div><div class="actions"><button class="btn primary" id="ci-btn">Generate citation</button><button class="btn secondary" id="ci-copy">Copy citation</button></div><div class="result" id="ci-out" style="display:none"></div>`, `Enter the author, title, year and source, pick APA or MLA, and get a formatted citation.`, ['readability-checker','flashcard-maker','word-counter','case-converter']); const out=$('#ci-out'),err=$('#ci-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} $('#ci-btn').addEventListener('click',()=>{hideErr();const author=$('#ci-author').value.trim(),title=$('#ci-title').value.trim(),year=$('#ci-year').value.trim(),source=$('#ci-source').value.trim(),style=$('#ci-style').value;if(!author||!title||!year||!source){showErr('Please fill in all four fields.');return;}const y=+year;if(!/^\d{4}$/.test(year)||y<1000||y>2100){showErr('Please enter a valid 4-digit year.');return;}out.textContent=style==='APA'?author+' ('+year+'). '+title+'. '+source+'.':author+'. "'+title+'." '+source+', '+year+'.';out.style.display='block';}); $('#ci-copy').addEventListener('click',()=>copy(out.textContent)); }
function pomodoroTimer(t){ window.__toolToken=(window.__toolToken||0)+1;const myToken=window.__toolToken; toolShell(t, `<div class="result"><div class="result-big" id="pom-mode">Focus</div><div class="result-big" id="pom-display">25:00</div><div id="pom-cycles">Completed focus sessions: 0</div></div><div class="actions"><button class="btn primary" id="pom-start">Start</button><button class="btn secondary" id="pom-pause">Pause</button><button class="btn secondary" id="pom-reset">Reset</button></div><p>Focus 25 minutes, then a 5-minute break. After every 4 focus sessions, take a 15-minute long break.</p>`, `Start the timer and work until it switches to a break. Pause to hold it, Reset to start over.`, ['countdown-timer','stopwatch','study-planner','readability-checker']); const display=$('#pom-display'),modeEl=$('#pom-mode'),cyclesEl=$('#pom-cycles'),startBtn=$('#pom-start'); const DUR={focus:25*60*1000,short:5*60*1000,long:15*60*1000}; const LABEL={focus:'Focus',short:'Short Break',long:'Long Break'}; let mode='focus',remainingMs=DUR.focus,endAt=0,iv=null,running=false,sessions=0; function show(ms){const s=Math.max(0,Math.ceil(ms/1000));display.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');modeEl.textContent=LABEL[mode];cyclesEl.textContent='Completed focus sessions: '+sessions;} function finish(){if(iv){clearInterval(iv);iv=null;}running=false;startBtn.textContent='Start';if(mode==='focus'){sessions++;if(sessions%4===0){mode='long';toast('Focus session done — time for a long break!');}else{mode='short';toast('Focus session done — time for a short break!');}}else{mode='focus';toast('Break over — back to focus!');}remainingMs=DUR[mode];show(remainingMs);} startBtn.addEventListener('click',()=>{if(running)return;endAt=Date.now()+remainingMs;running=true;startBtn.textContent='Running...';show(remainingMs);iv=setInterval(()=>{if(myToken!==window.__toolToken){clearInterval(iv);return;}remainingMs=endAt-Date.now();if(remainingMs<=0){finish();return;}show(remainingMs);},200);}); $('#pom-pause').addEventListener('click',()=>{if(!running)return;if(iv){clearInterval(iv);iv=null;}running=false;remainingMs=Math.max(0,endAt-Date.now());startBtn.textContent='Start';show(remainingMs);}); $('#pom-reset').addEventListener('click',()=>{if(iv){clearInterval(iv);iv=null;}running=false;mode='focus';sessions=0;remainingMs=DUR.focus;startBtn.textContent='Start';show(remainingMs);}); show(remainingMs); }
function flashcardMaker(t){ toolShell(t, `<div class="field"><label class="label" for="fc-q">Question</label><input class="input" id="fc-q" type="text" placeholder="e.g. What is the capital of France?"></div><div class="field"><label class="label" for="fc-a">Answer</label><input class="input" id="fc-a" type="text" placeholder="e.g. Paris"></div><div class="actions"><button class="btn primary" id="fc-add">Add card</button></div><div class="error" id="fc-err" style="display:none"></div><div class="result" id="fc-card"><div id="fc-count">No cards yet — add your first card above.</div><div class="result-big" id="fc-side" style="margin:12px 0"></div><div id="fc-hint"></div></div><div class="actions"><button class="btn secondary" id="fc-flip">Flip card</button><button class="btn secondary" id="fc-prev">Previous</button><button class="btn secondary" id="fc-next">Next</button></div>`, `Add question and answer cards, then flip a card to reveal the answer and step through the deck. Cards are kept only in this browser session.`, ['quiz-generator','readability-checker','study-planner','citation-generator']); const err=$('#fc-err'),countEl=$('#fc-count'),sideEl=$('#fc-side'),hintEl=$('#fc-hint'); let deck=[],idx=0,showing='q'; function showErr(m){err.textContent=m;err.style.display='block';} function hideErr(){err.textContent='';err.style.display='none';} function render(){if(!deck.length){countEl.textContent='No cards yet — add your first card above.';sideEl.textContent='';hintEl.textContent='';return;}countEl.textContent='Card '+(idx+1)+' of '+deck.length;sideEl.textContent=showing==='q'?deck[idx].q:deck[idx].a;hintEl.textContent=showing==='q'?'Question — press Flip card to see the answer.':'Answer — press Flip card to see the question again.';} $('#fc-add').addEventListener('click',()=>{hideErr();const q=$('#fc-q').value.trim(),a=$('#fc-a').value.trim();if(!q||!a){showErr('Please enter both a question and an answer.');return;}deck.push({q:q,a:a});idx=deck.length-1;showing='q';$('#fc-q').value='';$('#fc-a').value='';render();$('#fc-q').focus();}); $('#fc-flip').addEventListener('click',()=>{if(!deck.length)return;showing=showing==='q'?'a':'q';render();}); $('#fc-prev').addEventListener('click',()=>{if(!deck.length)return;if(idx>0){idx--;showing='q';render();}}); $('#fc-next').addEventListener('click',()=>{if(!deck.length)return;if(idx<deck.length-1){idx++;showing='q';render();}}); render(); }
function readabilityChecker(t){ toolShell(t, `<div class="field"><label class="label" for="rc-text">Your text</label><textarea class="textarea" id="rc-text" rows="8" placeholder="Paste your text here..."></textarea></div><div class="error" id="rc-err" style="display:none"></div><div class="actions"><button class="btn primary" id="rc-btn">Check readability</button><button class="btn secondary" id="rc-clear">Clear</button></div><div class="result" id="rc-out" style="display:none"></div>`, `Paste your text to get Flesch-Kincaid grade, Flesch reading ease, and word, sentence and syllable counts.`, ['word-counter','detailed-character-counter','citation-generator','flashcard-maker']); const out=$('#rc-out'),err=$('#rc-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} function syllables(word){const w=word.toLowerCase().replace(/[^a-z]/g,'');if(!w)return 0;const m=w.match(/[aeiouy]+/g);return m?Math.max(1,m.length):1;} $('#rc-btn').addEventListener('click',()=>{hideErr();const text=$('#rc-text').value.trim();if(!text){showErr('Please paste some text first.');return;}const words=text.split(/\s+/).filter(Boolean);const sentences=text.split(/[.!?]+/).map(s=>s.trim()).filter(Boolean);const sCount=sentences.length||1;const wCount=words.length;let syl=0;words.forEach(w=>{syl+=syllables(w);});const asl=wCount/sCount,asw=syl/wCount;const fre=206.835-1.015*asl-84.6*asw;const fk=0.39*asl+11.8*asw-15.59;let label='Very difficult';if(fre>=90)label='Very easy';else if(fre>=80)label='Easy';else if(fre>=70)label='Fairly easy';else if(fre>=60)label='Standard';else if(fre>=50)label='Fairly difficult';else if(fre>=30)label='Difficult';out.innerHTML='<div class="metric-grid">'+metric('Words',fmt(wCount))+metric('Sentences',fmt(sCount))+metric('Syllables',fmt(syl))+metric('Flesch-Kincaid grade',fk.toFixed(1))+metric('Flesch reading ease',fre.toFixed(1))+metric('Reading level',label)+'</div>';out.style.display='block';}); $('#rc-clear').addEventListener('click',()=>{$('#rc-text').value='';out.style.display='none';hideErr();}); }
function gradeCalc(t){ toolShell(t, `<div id="gc-rows"></div><div class="actions"><button class="btn secondary" id="gc-add">Add assignment</button></div><div class="error" id="gc-err" style="display:none"></div><div class="actions"><button class="btn primary" id="gc-btn">Calculate grade</button></div><div class="result" id="gc-out" style="display:none"></div>`, `Add one row per assignment with its score and weight, then calculate your weighted final grade and letter.`, ['gpa-calculator','percentage-calculator','average-calculator','study-planner']); const rows=$('#gc-rows'),err=$('#gc-err'),out=$('#gc-out'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} function addRow(name,score,weight){const d=document.createElement('div');d.className='row gc-row';d.innerHTML='<div class="field"><label class="label">Assignment</label><input class="input gc-name" type="text" placeholder="e.g. Midterm"></div><div class="field"><label class="label">Score (0-100)</label><input class="input gc-score" type="number" min="0" max="100" placeholder="e.g. 85"></div><div class="field"><label class="label">Weight %</label><input class="input gc-weight" type="number" min="0" max="100" placeholder="e.g. 30"></div><div class="field"><label class="label">&nbsp;</label><button class="btn secondary gc-remove">Remove</button></div>';rows.appendChild(d);const n=d.querySelector('.gc-name');n.value=name||'';d.querySelector('.gc-score').value=score==null?'':score;d.querySelector('.gc-weight').value=weight==null?'':weight;} rows.addEventListener('click',e=>{if(e.target.classList.contains('gc-remove')){e.target.closest('.gc-row').remove();}}); $('#gc-add').addEventListener('click',()=>addRow('','','')); $('#gc-btn').addEventListener('click',()=>{hideErr();const rs=$$('.gc-row');if(!rs.length){showErr('Add at least one assignment row.');return;}let num=0,den=0,ok=true;rs.forEach(r=>{const s=parseFloat(r.querySelector('.gc-score').value),w=parseFloat(r.querySelector('.gc-weight').value);if(isNaN(s)||isNaN(w)||s<0||s>100||w<0){ok=false;return;}num+=s*w;den+=w;});if(!ok){showErr('Please enter a score from 0 to 100 and a weight of 0 or more on every row.');return;}if(den<=0){showErr('Total weight must be more than 0.');return;}const final=num/den;const letter=final>=90?'A':final>=80?'B':final>=70?'C':final>=60?'D':'F';out.innerHTML='<div class="result-big">'+final.toFixed(2)+'% — Grade '+letter+'</div><div>Total weight: '+den+'%'+(den!==100?' (ideally 100% — the result is weighted against the total you entered)':'')+'</div>';out.style.display='block';}); addRow('Assignment 1','','');addRow('Assignment 2','','');addRow('Assignment 3','',''); }
function sciNotation(t){ toolShell(t, `<div class="field"><label class="label" for="sn-mode">Direction</label><select class="select" id="sn-mode"><option value="to-sci">Decimal → Scientific</option><option value="to-dec">Scientific → Decimal</option></select></div><div class="field"><label class="label" for="sn-input">Number</label><input class="input" id="sn-input" type="text" placeholder="e.g. 12300 or 1.23×10^4"></div><div class="error" id="sn-err" style="display:none"></div><div class="actions"><button class="btn primary" id="sn-btn">Convert</button><button class="btn secondary" id="sn-copy">Copy result</button></div><div class="result" id="sn-out" style="display:none"></div>`, `Convert a decimal number to scientific notation, or a scientific value like 1.23×10^4 (or 1.23e4) back to decimal.`, ['scientific-calculator','unit-converter','number-base-converter','percentage-calculator']); const out=$('#sn-out'),err=$('#sn-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} $('#sn-btn').addEventListener('click',()=>{hideErr();const mode=$('#sn-mode').value,raw=$('#sn-input').value.trim();if(!raw){showErr('Please enter a number.');return;}if(mode==='to-sci'){const n=Number(raw);if(!isFinite(n)){showErr('Please enter a valid decimal number.');return;}if(n===0){out.textContent='0 × 10^0';out.style.display='block';return;}const exp=Math.floor(Math.log10(Math.abs(n)));const mant=n/Math.pow(10,exp);let mStr=mant.toFixed(6).replace(/0+$/,'').replace(/\.$/,'');out.textContent=mStr+' × 10^'+exp;out.style.display='block';}else{let n=null;const m=raw.match(/^([+-]?[0-9]*\.?[0-9]+)\s*(?:×|\*|x)\s*10\^([+-]?\d+)$/);if(m){n=parseFloat(m[1])*Math.pow(10,parseInt(m[2],10));}else if(/^[+-]?[0-9]*\.?[0-9]+([eE][+-]?\d+)?$/.test(raw)){n=Number(raw);}if(n===null||!isFinite(n)){showErr('Please enter a scientific value like 1.23×10^4 or 1.23e4.');return;}out.textContent=String(n);out.style.display='block';}}); $('#sn-copy').addEventListener('click',()=>copy(out.textContent)); }
function multTable(t){ toolShell(t, `<div class="field"><label class="label" for="mt-n">Number (1-20)</label><input class="input" id="mt-n" type="number" min="1" max="20" value="7"></div><div class="error" id="mt-err" style="display:none"></div><div class="actions"><button class="btn primary" id="mt-btn">Show table</button><button class="btn secondary" id="mt-copy">Copy table</button></div><div id="mt-out"></div>`, `Enter a number from 1 to 20 to see its multiplication table from ×1 to ×12.`, ['scientific-calculator','average-calculator','grade-calculator','study-planner']); const out=$('#mt-out'),err=$('#mt-err'); let text=''; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} $('#mt-btn').addEventListener('click',()=>{hideErr();const n=parseInt($('#mt-n').value,10);if(isNaN(n)||n<1||n>20){showErr('Please enter a whole number from 1 to 20.');return;}const lines=[];let html='<table style="width:100%;border-collapse:collapse"><tr><th style="text-align:left;border:1px solid #ccc;padding:6px">Problem</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Answer</th></tr>';for(let i=1;i<=12;i++){lines.push(n+' × '+i+' = '+(n*i));html+='<tr><td style="border:1px solid #ccc;padding:6px">'+n+' × '+i+'</td><td style="border:1px solid #ccc;padding:6px">'+(n*i)+'</td></tr>';}html+='</table>';text='Multiplication table for '+n+'\n'+lines.join('\n');out.innerHTML=html;}); $('#mt-copy').addEventListener('click',()=>copy(text)); }
function studyPlanner(t){ toolShell(t, `<div id="sp-rows"></div><div class="actions"><button class="btn secondary" id="sp-add">Add subject</button></div><div class="error" id="sp-err" style="display:none"></div><div class="actions"><button class="btn primary" id="sp-btn">Build weekly schedule</button><button class="btn secondary" id="sp-copy">Copy schedule</button></div><div id="sp-out"></div>`, `Add up to 5 subjects with hours per week. Each subject's hours are spread evenly across Monday to Sunday.`, ['pomodoro-timer','flashcard-maker','grade-calculator','quiz-generator']); const rows=$('#sp-rows'),err=$('#sp-err'),out=$('#sp-out'); let text=''; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} function addRow(name,hours){const d=document.createElement('div');d.className='row sp-row';d.innerHTML='<div class="field"><label class="label">Subject</label><input class="input sp-name" type="text" placeholder="e.g. Maths"></div><div class="field"><label class="label">Hours per week</label><input class="input sp-hours" type="number" min="0.5" max="60" step="0.5" placeholder="e.g. 5"></div><div class="field"><label class="label">&nbsp;</label><button class="btn secondary sp-remove">Remove</button></div>';rows.appendChild(d);d.querySelector('.sp-name').value=name||'';d.querySelector('.sp-hours').value=hours==null?'':hours;} rows.addEventListener('click',e=>{if(e.target.classList.contains('sp-remove')){e.target.closest('.sp-row').remove();}}); $('#sp-add').addEventListener('click',()=>{if($$('.sp-row').length>=5){toast('You can add up to 5 subjects.');return;}addRow('','');}); $('#sp-btn').addEventListener('click',()=>{hideErr();const rs=$$('.sp-row');if(!rs.length){showErr('Add at least one subject.');return;}const subs=[];let ok=true;rs.forEach(r=>{const name=r.querySelector('.sp-name').value.trim(),h=parseFloat(r.querySelector('.sp-hours').value);if(!name||isNaN(h)||h<=0){ok=false;return;}subs.push({name:name,hours:h});});if(!ok){showErr('Please give every subject a name and hours per week above 0.');return;}const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let html='<table style="width:100%;border-collapse:collapse"><tr><th style="text-align:left;border:1px solid #ccc;padding:6px">Subject</th>'+days.map(d=>'<th style="text-align:left;border:1px solid #ccc;padding:6px">'+d+'</th>').join('')+'<th style="text-align:left;border:1px solid #ccc;padding:6px">Total</th></tr>';const lines=['Weekly study schedule'];let dayTotals=[0,0,0,0,0,0,0],grand=0;subs.forEach(s=>{const daily=Math.round((s.hours/7)*10)/10;dayTotals=dayTotals.map(v=>Math.round((v+daily)*10)/10);grand=Math.round((grand+s.hours)*10)/10;html+='<tr><td style="border:1px solid #ccc;padding:6px">'+esc(s.name)+'</td>'+days.map(()=>'<td style="border:1px solid #ccc;padding:6px">'+daily.toFixed(1)+'h</td>').join('')+'<td style="border:1px solid #ccc;padding:6px">'+s.hours+'h</td></tr>';lines.push(s.name+': '+daily.toFixed(1)+'h per day, '+s.hours+'h per week');});html+='<tr><td style="border:1px solid #ccc;padding:6px"><strong>Total</strong></td>'+dayTotals.map(v=>'<td style="border:1px solid #ccc;padding:6px"><strong>'+v.toFixed(1)+'h</strong></td>').join('')+'<td style="border:1px solid #ccc;padding:6px"><strong>'+grand+'h</strong></td></tr></table>';lines.push('Total: '+grand+'h per week');text=lines.join('\n');out.innerHTML=html;}); $('#sp-copy').addEventListener('click',()=>copy(text)); addRow('Maths','');addRow('English',''); }
function quizGen(t){ toolShell(t, `<div id="quiz-box"></div>`, `Answer 10 general knowledge questions, one at a time. Pick an option to see if it is right, then move to the next question for your score.`, ['flashcard-maker','study-planner','readability-checker','random-quote-generator']); const box=$('#quiz-box'); const qs=[{q:'What is the capital of France?',opts:['London','Berlin','Paris','Madrid'],a:2},{q:'What is the chemical symbol for gold?',opts:['Ag','Gd','Au','Go'],a:2},{q:'Which is the largest planet in our solar system?',opts:['Saturn','Jupiter','Neptune','Earth'],a:1},{q:'How many continents are there on Earth?',opts:['5','6','7','8'],a:2},{q:'Who wrote Romeo and Juliet?',opts:['Charles Dickens','William Shakespeare','Jane Austen','Mark Twain'],a:1},{q:'At sea level, water boils at which temperature?',opts:['90°C','95°C','100°C','110°C'],a:2},{q:'Which is the largest ocean on Earth?',opts:['Atlantic','Indian','Arctic','Pacific'],a:3},{q:'How many sides does a hexagon have?',opts:['5','6','7','8'],a:1},{q:'What is the currency of Japan?',opts:['Won','Yuan','Yen','Ringgit'],a:2},{q:'Which gas do plants absorb from the air?',opts:['Oxygen','Carbon dioxide','Nitrogen','Hydrogen'],a:1}]; let idx=0,score=0,answered=false; function render(){if(idx>=qs.length){box.innerHTML='<div class="result"><div class="result-big">Your score: '+score+' / '+qs.length+'</div><div>'+(score===qs.length?'Perfect score — well done!':score>=7?'Great job!':score>=4?'Good effort — try again to beat your score.':'Keep practising — you will do better next time.')+'</div><div class="actions"><button class="btn primary" id="quiz-restart">Restart quiz</button></div></div>';$('#quiz-restart').addEventListener('click',()=>{idx=0;score=0;render();});return;}const cur=qs[idx];answered=false;box.innerHTML='<div><p><strong>Question '+(idx+1)+' of '+qs.length+'</strong></p><p>'+esc(cur.q)+'</p><div id="quiz-opts">'+cur.opts.map((o,i)=>'<button class="btn secondary" data-opt="'+i+'" style="display:block;width:100%;text-align:left;margin-bottom:8px">'+esc(o)+'</button>').join('')+'</div><div id="quiz-feedback" style="margin:8px 0"></div><div class="actions"><button class="btn primary" id="quiz-next" style="display:none">Next question</button></div></div>';} box.addEventListener('click',e=>{const ob=e.target.closest('[data-opt]');if(ob&&!answered){answered=true;const chosen=+ob.dataset.opt;const cur=qs[idx];const fb=$('#quiz-feedback');$$('#quiz-opts button').forEach(b=>{b.disabled=true;});const correctBtn=$$('#quiz-opts button')[cur.a];correctBtn.style.background='#d1fae5';if(chosen===cur.a){score++;fb.textContent='Correct!';}else{ob.style.background='#fee2e2';fb.textContent='Not quite — the correct answer is '+cur.opts[cur.a]+'.';}$('#quiz-next').style.display='inline-block';return;}if(e.target.id==='quiz-next'){idx++;render();}}); render(); }
function invoiceGen(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="inv-biz">Your business name</label><input class="input" id="inv-biz" type="text" placeholder="e.g. Acme Studio"></div><div class="field"><label class="label" for="inv-client">Bill to (client)</label><input class="input" id="inv-client" type="text" placeholder="e.g. Jane Smith"></div></div><div class="row"><div class="field"><label class="label" for="inv-num">Invoice #</label><input class="input" id="inv-num" type="text" placeholder="e.g. INV-001" value="INV-001"></div><div class="field"><label class="label" for="inv-date">Date</label><input class="input" id="inv-date" type="date"></div><div class="field"><label class="label" for="inv-tax">Tax %</label><input class="input" id="inv-tax" type="number" min="0" max="100" step="0.1" value="0"></div></div><div class="field"><label class="label">Line items</label><div id="inv-rows"></div><button class="btn secondary" id="inv-add" type="button">Add item</button></div><div class="error" id="inv-err" style="display:none"></div><div class="actions"><button class="btn primary" id="inv-preview-btn">Preview invoice</button><button class="btn secondary" id="inv-print">Print</button><button class="btn secondary" id="inv-dl">Download .txt</button></div><div id="inv-preview"></div>`, `Enter your business and client details, add line items with quantity and price, set the tax %, then preview. Print it or download it as a text file.`, ['receipt-generator','price-calculator','profit-calculator','business-card-maker']); const rows=$('#inv-rows'),err=$('#inv-err'),preview=$('#inv-preview'); let lastText=''; function showErr(m){err.textContent=m;err.style.display='block';} function hideErr(){err.textContent='';err.style.display='none';} function addRow(desc,qty,price){const d=document.createElement('div');d.className='row inv-row';d.innerHTML='<div class="field"><label class="label">Description</label><input class="input inv-desc" type="text" placeholder="e.g. Design work"></div><div class="field"><label class="label">Qty</label><input class="input inv-qty" type="number" min="0" step="1" placeholder="1"></div><div class="field"><label class="label">Price each</label><input class="input inv-price" type="number" min="0" step="0.01" placeholder="0.00"></div><div class="field"><label class="label">&nbsp;</label><button class="btn secondary inv-remove" type="button">Remove</button></div>';rows.appendChild(d);d.querySelector('.inv-desc').value=desc||'';d.querySelector('.inv-qty').value=qty==null?'':qty;d.querySelector('.inv-price').value=price==null?'':price;} rows.addEventListener('click',function(e){if(e.target.classList.contains('inv-remove')){e.target.closest('.inv-row').remove();}}); $('#inv-add').addEventListener('click',function(){addRow('','','');}); function collect(){hideErr();const items=[];let ok=true;$$('.inv-row').forEach(function(r){const desc=r.querySelector('.inv-desc').value.trim();const q=parseFloat(r.querySelector('.inv-qty').value);const p=parseFloat(r.querySelector('.inv-price').value);if(!desc&&isNaN(q)&&isNaN(p)){return;}if(!desc||isNaN(q)||isNaN(p)||q<=0||p<0){ok=false;return;}items.push({desc:desc,qty:q,price:p});});if(!ok){showErr('Each item needs a description, a quantity above 0 and a price of 0 or more.');return null;}if(!items.length){showErr('Add at least one line item.');return null;}const biz=$('#inv-biz').value.trim(),client=$('#inv-client').value.trim(),num=$('#inv-num').value.trim()||'INV-001',date=$('#inv-date').value||'',tax=parseFloat($('#inv-tax').value);if(isNaN(tax)||tax<0||tax>100){showErr('Tax must be between 0 and 100%.');return null;}let sub=0;items.forEach(function(it){sub+=it.qty*it.price;});const taxAmt=sub*tax/100,total=sub+taxAmt;return {biz:biz,client:client,num:num,date:date,tax:tax,items:items,sub:sub,taxAmt:taxAmt,total:total};} function buildText(d){const lines=[];lines.push('INVOICE '+d.num);if(d.biz){lines.push(d.biz);}if(d.client){lines.push('Bill to: '+d.client);}if(d.date){lines.push('Date: '+d.date);}lines.push('');d.items.forEach(function(it){lines.push(it.desc+' — '+it.qty+' x $'+it.price.toFixed(2)+' = $'+(it.qty*it.price).toFixed(2));});lines.push('');lines.push('Subtotal: $'+d.sub.toFixed(2));lines.push('Tax ('+d.tax+'%): $'+d.taxAmt.toFixed(2));lines.push('Total: $'+d.total.toFixed(2));return lines.join('\n');} function renderPreview(){const d=collect();if(!d){return false;}lastText=buildText(d);preview.innerHTML='<div class="result"><h3>Invoice '+esc(d.num)+'</h3>'+(d.biz?'<p><strong>'+esc(d.biz)+'</strong></p>':'')+(d.client?'<p>Bill to: '+esc(d.client)+'</p>':'')+(d.date?'<p>Date: '+esc(d.date)+'</p>':'')+'<table style="width:100%;border-collapse:collapse;margin:12px 0"><tr><th style="text-align:left;border:1px solid #ccc;padding:6px">Item</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Qty</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Price</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Amount</th></tr>'+d.items.map(function(it){return '<tr><td style="border:1px solid #ccc;padding:6px">'+esc(it.desc)+'</td><td style="border:1px solid #ccc;padding:6px">'+it.qty+'</td><td style="border:1px solid #ccc;padding:6px">$'+it.price.toFixed(2)+'</td><td style="border:1px solid #ccc;padding:6px">$'+(it.qty*it.price).toFixed(2)+'</td></tr>';}).join('')+'</table><p>Subtotal: $'+d.sub.toFixed(2)+'</p><p>Tax ('+d.tax+'%): $'+d.taxAmt.toFixed(2)+'</p><p><strong>Total: $'+d.total.toFixed(2)+'</strong></p></div>';return true;} $('#inv-preview-btn').addEventListener('click',function(){renderPreview();}); $('#inv-print').addEventListener('click',function(){if(renderPreview()){window.print();}}); $('#inv-dl').addEventListener('click',function(){if(!lastText&&!renderPreview()){return;}downloadText(lastText,'invoice.txt');}); $('#inv-date').value=new Date().toISOString().slice(0,10); addRow('','1','');addRow('','1',''); }
function businessNameGen(t){ toolShell(t, `<div class="field"><label class="label" for="bn-kw">Keyword</label><input class="input" id="bn-kw" type="text" placeholder="e.g. bloom, pixel, summit"></div><div class="field"><label class="label" for="bn-industry">Industry</label><select class="select" id="bn-industry"><option value="Technology">Technology</option><option value="Food & Drink">Food & Drink</option><option value="Fashion">Fashion</option><option value="Fitness">Fitness</option><option value="Finance">Finance</option><option value="Travel">Travel</option><option value="Beauty">Beauty</option><option value="Education">Education</option><option value="Home Services">Home Services</option><option value="Pets">Pets</option></select></div><div class="error" id="bn-err" style="display:none"></div><div class="actions"><button class="btn primary" id="bn-btn">Generate names</button></div><div id="bn-out"></div>`, `Enter a keyword, pick your industry, and get 10 name ideas. Copy any name to use it.`, ['slogan-generator','logo-maker','business-card-maker','bio-generator']); const out=$('#bn-out'),err=$('#bn-err'); let items=[]; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} out.addEventListener('click',function(e){const b=e.target.closest('[data-copy]');if(!b){return;}copy(items[+b.dataset.copy]);}); $('#bn-btn').addEventListener('click',function(){hideErr();const kw=$('#bn-kw').value.trim(),industry=$('#bn-industry').value;const bare=kw.replace(/[^a-zA-Z0-9]/g,'');if(!bare){showErr('Please enter a keyword (letters or numbers).');return;}const cap=bare.charAt(0).toUpperCase()+bare.slice(1);const words={Technology:'Tech','Food & Drink':'Eats',Fashion:'Style',Fitness:'Fit',Finance:'Capital',Travel:'Journeys',Beauty:'Glow',Education:'Learn','Home Services':'Home',Pets:'Paws'};const indWord=words[industry]||'Co';items=[cap+'ly','The '+cap+' Co.',cap+' Labs','Go'+cap,cap+'Hub','True'+cap,cap+' & Co.','My'+cap,cap+'Works',cap+indWord];out.innerHTML='<p>10 name ideas for <strong>'+esc(industry)+'</strong> — keyword "'+esc(kw)+'"</p>'+items.map(function(s,i){return '<div class="result"><div>'+esc(s)+'</div><div class="actions"><button class="btn secondary" data-copy="'+i+'">Copy</button></div></div>';}).join('');}); }
function sloganGen(t){ toolShell(t, `<div class="field"><label class="label" for="sl-product">Product or brand</label><input class="input" id="sl-product" type="text" placeholder="e.g. Luna Coffee, your fitness app"></div><div class="field"><label class="label" for="sl-tone">Tone</label><select class="select" id="sl-tone"><option value="Bold">Bold</option><option value="Friendly">Friendly</option><option value="Professional">Professional</option><option value="Fun">Fun</option><option value="Inspiring">Inspiring</option></select></div><div class="error" id="sl-err" style="display:none"></div><div class="actions"><button class="btn primary" id="sl-btn">Generate slogans</button></div><div id="sl-out"></div>`, `Enter your product or brand, pick a tone, and get 8 slogans. Copy any slogan to use it.`, ['business-name-generator','logo-maker','youtube-title-generator','ai-caption-generator']); const out=$('#sl-out'),err=$('#sl-err'); let items=[]; function showErr(m){err.textContent=m;err.style.display='block';out.innerHTML='';} function hideErr(){err.textContent='';err.style.display='none';} out.addEventListener('click',function(e){const b=e.target.closest('[data-copy]');if(!b){return;}copy(items[+b.dataset.copy]);}); $('#sl-btn').addEventListener('click',function(){hideErr();const product=$('#sl-product').value.trim(),tone=$('#sl-tone').value;if(!product){showErr('Please enter your product or brand.');return;}const banks={Bold:['{K}. No excuses.','Built for {K}. Built to win.','{K} — done right, done bold.','Stop settling. Choose {K}.','{K} that works as hard as you do.','Real {K}. Real results.','{K}: louder, stronger, better.','Own it with {K}.'],Friendly:['{K} that feels like home.','Good days start with {K}.','Made with care. Made for {K}.','{K} — simple, honest, yours.','Your friendly {K}, every day.','{K} that puts a smile first.','Little moments, better with {K}.','We love {K}. You will too.'],Professional:['{K}, delivered with precision.','Trusted {K} for serious results.','The professional choice in {K}.','{K} — quality you can measure.','Excellence in every {K}.','Dependable {K}, on time, every time.','{K} that meets the highest standard.','Serious {K} for serious people.'],Fun:['{K} with a wink.','Life is short. Grab {K}.','{K} — now with extra sparkle.','Warning: {K} may cause happiness.','Fun starts with {K}.','{K}: the good kind of trouble.','Turn up the fun with {K}.','{K} so good, it should be illegal.'],Inspiring:['Dream bigger with {K}.','{K}: where ambitions take flight.','Your journey begins with {K}.','Believe in better. Believe in {K}.','{K} — made for what is next.','One step with {K} changes everything.','Reach higher with {K}.','{K}: the start of something great.']};items=(banks[tone]||banks.Bold).map(function(s){return s.split('{K}').join(product);});out.innerHTML=items.map(function(s,i){return '<div class="result"><div>'+esc(s)+'</div><div class="actions"><button class="btn secondary" data-copy="'+i+'">Copy</button></div></div>';}).join('');}); }
function logoMaker(t){ toolShell(t, `<div class="field"><label class="label" for="lm-name">Business name</label><input class="input" id="lm-name" type="text" placeholder="e.g. Luna Coffee" value="Your Brand"></div><div class="row"><div class="field"><label class="label" for="lm-shape">Shape</label><select class="select" id="lm-shape"><option value="circle">Circle</option><option value="square">Square</option><option value="star">Star</option></select></div><div class="field"><label class="label" for="lm-c1">Shape color</label><input class="input" id="lm-c1" type="color" value="#FF4D24"></div><div class="field"><label class="label" for="lm-c2">Text color</label><input class="input" id="lm-c2" type="color" value="#1B2436"></div></div><div class="actions"><button class="btn primary" id="lm-draw">Draw logo</button><button class="btn secondary" id="lm-dl">Download PNG</button></div><canvas id="lm-canvas" width="600" height="400" style="max-width:100%;height:auto;border:1px solid #ddd;border-radius:8px"></canvas>`, `Enter your business name, pick a shape and two colors, then draw your logo. Download it as a PNG.`, ['business-name-generator','slogan-generator','business-card-maker','ai-logo-generator']); function draw(){const cv=$('#lm-canvas');const ctx=cv.getContext('2d');const name=($('#lm-name').value||'').trim()||'Your Brand';const shape=$('#lm-shape').value;const c1=$('#lm-c1').value||'#FF4D24';const c2=$('#lm-c2').value||'#1B2436';ctx.fillStyle='#ffffff';ctx.fillRect(0,0,600,400);ctx.fillStyle=c1;ctx.beginPath();if(shape==='square'){ctx.rect(190,70,220,220);}else if(shape==='star'){const cx=300,cy=180;for(let i=0;i<10;i++){const r=i%2===0?120:50;const a=-Math.PI/2+i*Math.PI/5;const x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;if(i===0){ctx.moveTo(x,y);}else{ctx.lineTo(x,y);}}ctx.closePath();}else{ctx.arc(300,180,120,0,Math.PI*2);}ctx.fill();ctx.fillStyle=c2;ctx.textAlign='center';ctx.textBaseline='middle';const fs=name.length>16?28:44;ctx.font='800 '+fs+'px sans-serif';ctx.fillText(name,300,360,560);} $('#lm-draw').addEventListener('click',draw); $('#lm-dl').addEventListener('click',function(){draw();const cv=$('#lm-canvas');download(cv.toDataURL('image/png'),safeName(($('#lm-name').value||'logo').trim()||'logo','.png'));}); draw(); }
function businessCardMaker(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="bc-name">Full name</label><input class="input" id="bc-name" type="text" placeholder="e.g. Alex Carter" value="Alex Carter"></div><div class="field"><label class="label" for="bc-title">Job title</label><input class="input" id="bc-title" type="text" placeholder="e.g. Founder & Designer" value="Founder & Designer"></div></div><div class="row"><div class="field"><label class="label" for="bc-phone">Phone</label><input class="input" id="bc-phone" type="text" placeholder="e.g. +1 555 123 4567" value="+1 555 123 4567"></div><div class="field"><label class="label" for="bc-email">Email</label><input class="input" id="bc-email" type="text" placeholder="e.g. alex@example.com" value="alex@example.com"></div></div><div class="row"><div class="field"><label class="label" for="bc-company">Company</label><input class="input" id="bc-company" type="text" placeholder="e.g. Acme Studio" value="Acme Studio"></div><div class="field"><label class="label" for="bc-accent">Accent color</label><input class="input" id="bc-accent" type="color" value="#FF4D24"></div></div><div class="actions"><button class="btn primary" id="bc-draw">Draw card</button><button class="btn secondary" id="bc-dl">Download PNG</button></div><canvas id="bc-canvas" width="900" height="500" style="max-width:100%;height:auto;border:1px solid #ddd;border-radius:8px"></canvas>`, `Enter your name, title, phone, email and company, pick an accent color, then draw your card. Download it as a PNG.`, ['logo-maker','invoice-generator','receipt-generator','business-name-generator']); function draw(){const cv=$('#bc-canvas');const ctx=cv.getContext('2d');const name=($('#bc-name').value||'').trim()||'Your Name';const title=($('#bc-title').value||'').trim()||'Your Title';const phone=($('#bc-phone').value||'').trim();const email=($('#bc-email').value||'').trim();const company=($('#bc-company').value||'').trim()||'Your Company';const accent=$('#bc-accent').value||'#FF4D24';ctx.fillStyle='#141B2A';ctx.fillRect(0,0,900,500);ctx.fillStyle=accent;ctx.fillRect(0,0,18,500);ctx.fillStyle=accent;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.font='700 26px sans-serif';ctx.fillText(company.toUpperCase(),48,72,780);ctx.fillStyle='#ffffff';ctx.font='800 54px sans-serif';ctx.fillText(name,48,200,780);ctx.fillStyle='#C7CEDB';ctx.font='400 28px sans-serif';ctx.fillText(title,48,250,780);ctx.fillStyle=accent;ctx.fillRect(48,300,120,4);ctx.fillStyle='#E8ECF2';ctx.font='400 24px sans-serif';let y=360;if(phone){ctx.fillText(phone,48,y,780);y+=40;}if(email){ctx.fillText(email,48,y,780);y+=40;}} $('#bc-draw').addEventListener('click',draw); $('#bc-dl').addEventListener('click',function(){draw();const cv=$('#bc-canvas');download(cv.toDataURL('image/png'),safeName(($('#bc-name').value||'business-card').trim()||'business-card','.png'));}); draw(); }
function priceCalc(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="prc-cost">Cost per unit ($)</label><input class="input" id="prc-cost" type="number" min="0" step="0.01" placeholder="e.g. 40"></div><div class="field"><label class="label" for="prc-margin">Target margin %</label><input class="input" id="prc-margin" type="number" min="0" max="99.99" step="0.1" placeholder="e.g. 30"></div></div><div class="error" id="prc-err" style="display:none"></div><div class="actions"><button class="btn primary" id="prc-btn">Calculate price</button></div><div class="result" id="prc-out" style="display:none"></div>`, `Enter your cost per unit and the margin % you want. Selling price is cost divided by (1 minus margin as a decimal).`, ['profit-calculator','break-even-calculator','percentage-calculator','invoice-generator']); const out=$('#prc-out'),err=$('#prc-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} $('#prc-btn').addEventListener('click',function(){hideErr();const cost=parseFloat($('#prc-cost').value);const margin=parseFloat($('#prc-margin').value);if(isNaN(cost)||cost<0){showErr('Please enter a cost of 0 or more.');return;}if(isNaN(margin)||margin<0||margin>=100){showErr('Margin must be from 0 up to (but not including) 100%.');return;}const price=cost/(1-margin/100);const profit=price-cost;out.innerHTML='<div class="metric-grid">'+metric('Selling price','$'+price.toFixed(2))+metric('Profit per unit','$'+profit.toFixed(2))+metric('Margin',margin.toFixed(2)+'%')+'</div>';out.style.display='block';}); }
function profitCalc(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="pf-rev">Total revenue ($)</label><input class="input" id="pf-rev" type="number" min="0" step="0.01" placeholder="e.g. 1000"></div><div class="field"><label class="label" for="pf-cost">Total cost ($)</label><input class="input" id="pf-cost" type="number" min="0" step="0.01" placeholder="e.g. 600"></div></div><div class="error" id="pf-err" style="display:none"></div><div class="actions"><button class="btn primary" id="pf-btn">Calculate profit</button></div><div class="result" id="pf-out" style="display:none"></div>`, `Enter total revenue and total cost. Profit is revenue minus cost; margin is profit divided by revenue, times 100.`, ['price-calculator','break-even-calculator','percentage-calculator','invoice-generator']); const out=$('#pf-out'),err=$('#pf-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} $('#pf-btn').addEventListener('click',function(){hideErr();const rev=parseFloat($('#pf-rev').value);const cost=parseFloat($('#pf-cost').value);if(isNaN(rev)||rev<0){showErr('Please enter revenue of 0 or more.');return;}if(isNaN(cost)||cost<0){showErr('Please enter cost of 0 or more.');return;}const profit=rev-cost;const margin=rev===0?0:(profit/rev*100);out.innerHTML='<div class="metric-grid">'+metric('Profit','$'+profit.toFixed(2))+metric('Margin',margin.toFixed(2)+'%')+metric('Revenue','$'+rev.toFixed(2))+metric('Cost','$'+cost.toFixed(2))+'</div>';out.style.display='block';}); }
function breakEvenCalc(t){ toolShell(t, `<div class="field"><label class="label" for="be-fixed">Fixed costs ($)</label><input class="input" id="be-fixed" type="number" min="0" step="0.01" placeholder="e.g. 5000"></div><div class="row"><div class="field"><label class="label" for="be-price">Selling price per unit ($)</label><input class="input" id="be-price" type="number" min="0" step="0.01" placeholder="e.g. 50"></div><div class="field"><label class="label" for="be-var">Variable cost per unit ($)</label><input class="input" id="be-var" type="number" min="0" step="0.01" placeholder="e.g. 30"></div></div><div class="error" id="be-err" style="display:none"></div><div class="actions"><button class="btn primary" id="be-btn">Calculate break-even</button></div><div class="result" id="be-out" style="display:none"></div>`, `Enter fixed costs, selling price per unit and variable cost per unit. Break-even units are fixed costs divided by (price minus variable cost).`, ['price-calculator','profit-calculator','meeting-cost-calculator','percentage-calculator']); const out=$('#be-out'),err=$('#be-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} $('#be-btn').addEventListener('click',function(){hideErr();const fixed=parseFloat($('#be-fixed').value);const price=parseFloat($('#be-price').value);const vc=parseFloat($('#be-var').value);if(isNaN(fixed)||fixed<0){showErr('Please enter fixed costs of 0 or more.');return;}if(isNaN(price)||price<=0){showErr('Please enter a selling price above 0.');return;}if(isNaN(vc)||vc<0){showErr('Please enter a variable cost of 0 or more.');return;}if(price<=vc){showErr('Selling price must be above variable cost per unit, or you never break even.');return;}const units=fixed/(price-vc);const revenue=units*price;out.innerHTML='<div class="metric-grid">'+metric('Break-even units',fmt(Math.ceil(units))+' units')+metric('Exact break-even',units.toFixed(2)+' units')+metric('Revenue at break-even','$'+revenue.toFixed(2))+'</div>';out.style.display='block';}); }
function meetingCostCalc(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="mc-people">People in the meeting</label><input class="input" id="mc-people" type="number" min="1" step="1" placeholder="e.g. 5"></div><div class="field"><label class="label" for="mc-rate">Average hourly rate ($)</label><input class="input" id="mc-rate" type="number" min="0" step="0.01" placeholder="e.g. 40"></div><div class="field"><label class="label" for="mc-hours">Duration (hours)</label><input class="input" id="mc-hours" type="number" min="0" step="0.25" placeholder="e.g. 1.5"></div></div><div class="error" id="mc-err" style="display:none"></div><div class="actions"><button class="btn primary" id="mc-btn">Calculate meeting cost</button></div><div class="result" id="mc-out" style="display:none"></div>`, `Enter headcount, average hourly rate and duration. Total cost is people times rate times hours.`, ['break-even-calculator','profit-calculator','price-calculator','pomodoro-timer']); const out=$('#mc-out'),err=$('#mc-err'); function showErr(m){err.textContent=m;err.style.display='block';out.style.display='none';} function hideErr(){err.textContent='';err.style.display='none';} $('#mc-btn').addEventListener('click',function(){hideErr();const people=parseFloat($('#mc-people').value);const rate=parseFloat($('#mc-rate').value);const hours=parseFloat($('#mc-hours').value);if(isNaN(people)||people<1){showErr('Please enter at least 1 person.');return;}if(isNaN(rate)||rate<0){showErr('Please enter an hourly rate of 0 or more.');return;}if(isNaN(hours)||hours<=0){showErr('Please enter a duration above 0 hours.');return;}const total=people*rate*hours;const perMin=total/(hours*60);out.innerHTML='<div class="metric-grid">'+metric('Total meeting cost','$'+total.toFixed(2))+metric('Cost per minute','$'+perMin.toFixed(2))+metric('Cost per person','$'+(total/people).toFixed(2))+'</div>';out.style.display='block';}); }
function receiptGen(t){ toolShell(t, `<div class="row"><div class="field"><label class="label" for="rct-biz">Business name</label><input class="input" id="rct-biz" type="text" placeholder="e.g. Acme Studio"></div><div class="field"><label class="label" for="rct-pay">Payment method</label><select class="select" id="rct-pay"><option value="Cash">Cash</option><option value="Card">Card</option><option value="Bank transfer">Bank transfer</option><option value="Mobile wallet">Mobile wallet</option></select></div></div><div class="field"><label class="label">Items (up to 8)</label><div id="rct-rows"></div><button class="btn secondary" id="rct-add" type="button">Add item</button></div><div class="error" id="rct-err" style="display:none"></div><div class="actions"><button class="btn primary" id="rct-preview-btn">Preview receipt</button><button class="btn secondary" id="rct-print">Print</button><button class="btn secondary" id="rct-dl">Download .txt</button></div><div id="rct-preview"></div>`, `Enter your business name and payment method, add up to 8 items with amounts, then preview. Print it or download it as a text file.`, ['invoice-generator','business-card-maker','price-calculator','profit-calculator']); const rows=$('#rct-rows'),err=$('#rct-err'),preview=$('#rct-preview'); let lastText=''; function showErr(m){err.textContent=m;err.style.display='block';} function hideErr(){err.textContent='';err.style.display='none';} function addRow(desc,amount){const d=document.createElement('div');d.className='row rct-row';d.innerHTML='<div class="field"><label class="label">Description</label><input class="input rct-desc" type="text" placeholder="e.g. Coffee"></div><div class="field"><label class="label">Amount ($)</label><input class="input rct-amount" type="number" min="0" step="0.01" placeholder="0.00"></div><div class="field"><label class="label">&nbsp;</label><button class="btn secondary rct-remove" type="button">Remove</button></div>';rows.appendChild(d);d.querySelector('.rct-desc').value=desc||'';d.querySelector('.rct-amount').value=amount==null?'':amount;} rows.addEventListener('click',function(e){if(e.target.classList.contains('rct-remove')){e.target.closest('.rct-row').remove();}}); $('#rct-add').addEventListener('click',function(){if($$('.rct-row').length>=8){toast('Up to 8 items per receipt.');return;}addRow('','');}); function collect(){hideErr();const items=[];let ok=true;$$('.rct-row').forEach(function(r){const desc=r.querySelector('.rct-desc').value.trim();const a=parseFloat(r.querySelector('.rct-amount').value);if(!desc&&isNaN(a)){return;}if(!desc||isNaN(a)||a<0){ok=false;return;}items.push({desc:desc,amount:a});});if(!ok){showErr('Each item needs a description and an amount of 0 or more.');return null;}if(!items.length){showErr('Add at least one item.');return null;}const biz=$('#rct-biz').value.trim();const pay=$('#rct-pay').value;let total=0;items.forEach(function(it){total+=it.amount;});return {biz:biz,pay:pay,items:items,total:total,date:new Date().toISOString().slice(0,10)};} function buildText(d){const lines=[];lines.push('RECEIPT');if(d.biz){lines.push(d.biz);}lines.push('Date: '+d.date);lines.push('Payment: '+d.pay);lines.push('');d.items.forEach(function(it){lines.push(it.desc+' — $'+it.amount.toFixed(2));});lines.push('');lines.push('Total: $'+d.total.toFixed(2));lines.push('Thank you!');return lines.join('\n');} function renderPreview(){const d=collect();if(!d){return false;}lastText=buildText(d);preview.innerHTML='<div class="result"><h3>Receipt</h3>'+(d.biz?'<p><strong>'+esc(d.biz)+'</strong></p>':'')+'<p>Date: '+esc(d.date)+'</p><p>Payment: '+esc(d.pay)+'</p><table style="width:100%;border-collapse:collapse;margin:12px 0"><tr><th style="text-align:left;border:1px solid #ccc;padding:6px">Item</th><th style="text-align:left;border:1px solid #ccc;padding:6px">Amount</th></tr>'+d.items.map(function(it){return '<tr><td style="border:1px solid #ccc;padding:6px">'+esc(it.desc)+'</td><td style="border:1px solid #ccc;padding:6px">$'+it.amount.toFixed(2)+'</td></tr>';}).join('')+'</table><p><strong>Total: $'+d.total.toFixed(2)+'</strong></p><p>Thank you!</p></div>';return true;} $('#rct-preview-btn').addEventListener('click',function(){renderPreview();}); $('#rct-print').addEventListener('click',function(){if(renderPreview()){window.print();}}); $('#rct-dl').addEventListener('click',function(){if(!lastText&&!renderPreview()){return;}downloadText(lastText,'receipt.txt');}); addRow('','');addRow('',''); }

const __libCache={};
function loadLib(url,key){if(window[key])return Promise.resolve(true);if(__libCache[url])return __libCache[url];__libCache[url]=new Promise(function(res){var s=document.createElement('script');s.src=url;s.onload=function(){res(!!window[key])};s.onerror=function(){res(false)};document.head.appendChild(s)});return __libCache[url]}
function jsonToCsvText(src){var data=JSON.parse(src);if(!Array.isArray(data))data=[data];if(!data.length)return '';var keys=[],seen={};data.forEach(function(r){if(r&&typeof r==='object'){Object.keys(r).forEach(function(k){if(!seen[k]){seen[k]=1;keys.push(k)}})}});if(!keys.length)keys=['value'];function cell(v){if(v===null||v===undefined)return '';var s=(typeof v==='object')?JSON.stringify(v):String(v);return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}var lines=[keys.map(cell).join(',')];data.forEach(function(r){if(r&&typeof r==='object'){lines.push(keys.map(function(k){return cell(r[k])}).join(','))}else{lines.push(cell(r))}});return lines.join('\n')}
function parseCsvRows(text,delim){var rows=[],row=[],cur='',inQ=false,i,c;for(i=0;i<text.length;i++){c=text[i];if(inQ){if(c==='"'){if(text[i+1]==='"'){cur+='"';i++}else inQ=false}else cur+=c}else if(c==='"')inQ=true;else if(c===delim){row.push(cur);cur=''}else if(c==='\n'){row.push(cur);rows.push(row);row=[];cur=''}else if(c==='\r'){}else cur+=c}if(cur!==''||row.length){row.push(cur);rows.push(row)}return rows.filter(function(r){return !(r.length===1&&r[0].trim()==='')})}
function csvToJsonText(src){var first=src.split(/\r?\n/).find(function(l){return l.trim()!==''})||'';var cands=[',',';','\t','|'],delim=',',best=-1;cands.forEach(function(d){var n=first.split(d).length-1;if(n>best){best=n;delim=d}});var rows=parseCsvRows(src,delim);if(!rows.length)return '[]';var heads=rows[0].map(function(h,i){return h.trim()||('column'+(i+1))});var objs=rows.slice(1).map(function(r){var o={};heads.forEach(function(h,i){o[h]=r[i]===undefined?'':r[i]});return o});return JSON.stringify(objs,null,2)}
function slugifyText(s,sep,lower){var out=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(lower!==false)out=out.toLowerCase();out=out.replace(/[^a-zA-Z0-9]+/g,sep).replace(new RegExp('^\\'+sep+'+|\\'+sep+'+$','g'),'').replace(new RegExp('\\'+sep+'{2,}','g'),sep);return out}
function barcodeTool(t){toolShell(t,`<div class="field"><label class="label" for="bc-text">Barcode content</label><input class="input" id="bc-text" placeholder="e.g. 5901234123457 (EAN-13) or any text (Code 128)"></div><div class="row"><div class="field"><label class="label" for="bc-format">Format</label><select class="select" id="bc-format"><option value="CODE128" selected>Code 128 — any text</option><option value="CODE39">Code 39</option><option value="EAN13">EAN-13 — 12 or 13 digits</option><option value="EAN8">EAN-8 — 7 or 8 digits</option><option value="UPC">UPC — 11 or 12 digits</option><option value="ITF14">ITF-14 — 13 or 14 digits</option></select></div><div class="field"><label class="label" for="bc-width">Bar width: <span id="bc-width-val">2</span></label><input class="range" id="bc-width" type="range" min="1" max="4" step="1" value="2"></div></div><div class="field"><label class="label" for="bc-height">Height: <span id="bc-height-val">80</span> px</label><input class="range" id="bc-height" type="range" min="40" max="160" step="5" value="80"></div><label class="switch-row"><input type="checkbox" id="bc-showtext" checked> Show the value under the bars</label><div id="bc-error"></div><div class="actions"><button class="btn primary" id="bc-run">Generate barcode</button><button class="btn secondary" id="bc-png" disabled>Download PNG</button><button class="btn secondary" id="bc-svg" disabled>Download SVG</button></div><div class="result" id="bc-out" hidden style="text-align:center;background:#fff;padding:16px"><svg id="bc-svg-el" role="img" aria-label="Generated barcode"></svg></div>`,`Type the value, choose a format — Code 128 accepts any text, while EAN and UPC need the right number of digits — then generate and download.`,['qr-code-generator','password-generator','uuid-generator']);var err=$('#bc-error');function fail(m){err.innerHTML='<div class="error">'+m+'</div>'}function draw(){err.innerHTML='';var val=$('#bc-text').value.trim();if(!val){fail('Enter the text or number to encode first.');return false}try{JsBarcode('#bc-svg-el',val,{format:$('#bc-format').value,width:+$('#bc-width').value,height:+$('#bc-height').value,displayValue:$('#bc-showtext').checked,margin:10});$('#bc-out').hidden=false;$('#bc-png').disabled=false;$('#bc-svg').disabled=false;return true}catch(e){fail('That value does not fit the chosen format. EAN-13 needs 12 or 13 digits, EAN-8 needs 7 or 8, UPC needs 11 or 12, ITF-14 needs 13 or 14.');return false}}$('#bc-width').oninput=function(){$('#bc-width-val').textContent=this.value};$('#bc-height').oninput=function(){$('#bc-height-val').textContent=this.value};$('#bc-run').onclick=function(){if(window.JsBarcode){draw()}else{fail('Loading the barcode library…');loadLib('https://cdnjs.cloudflare.com/ajax/libs/jsbarcode/3.11.6/JsBarcode.all.min.js','JsBarcode').then(function(ok){if(ok)draw();else fail('The barcode library could not load — check your connection and retry.')})}};function svgString(){return new XMLSerializer().serializeToString($('#bc-svg-el'))}$('#bc-svg').onclick=function(){var blob=new Blob([svgString()],{type:'image/svg+xml;charset=utf-8'});var u=URL.createObjectURL(blob);download(u,'hectool-barcode.svg');setTimeout(function(){URL.revokeObjectURL(u)},4000)};$('#bc-png').onclick=function(){var svg=$('#bc-svg-el');var w=svg.viewBox&&svg.viewBox.baseVal&&svg.viewBox.baseVal.width?svg.viewBox.baseVal.width:(+$('#bc-height').value*4);var h=svg.viewBox&&svg.viewBox.baseVal&&svg.viewBox.baseVal.height?svg.viewBox.baseVal.height:(+$('#bc-height').value+30);var img=new Image();var u=URL.createObjectURL(new Blob([svgString()],{type:'image/svg+xml;charset=utf-8'}));img.onload=function(){var c=document.createElement('canvas');c.width=w*3;c.height=h*3;var x=c.getContext('2d');x.fillStyle='#ffffff';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(u);download(c.toDataURL('image/png'),'hectool-barcode.png')};img.onerror=function(){URL.revokeObjectURL(u);fail('Could not build the PNG. Try the SVG download instead.')};img.src=u}}
function pdfOrganizer(t){toolShell(t,`<div class="field"><label class="label" for="po-file">Choose a PDF</label><input class="input" id="po-file" type="file" accept="application/pdf,.pdf"></div><div class="result" id="po-list" hidden></div><div id="po-error"></div><div class="actions"><button class="btn primary" id="po-download" disabled>Download organized PDF</button></div><div class="result" id="po-result"></div>`,`Choose a PDF, then use the arrows to reorder pages, the rotate button to turn a page, or remove to drop a page — then download the reorganized PDF.`,['pdf-rotator','pdf-page-deleter','pdf-splitter','pdf-merger']);var order=[],rots=[],origRots=[],pageCount=0,theFile=null;var listEl=$('#po-list'),errEl=$('#po-error');function renderList(){if(!order.length){listEl.hidden=true;$('#po-download').disabled=true;return}listEl.hidden=false;$('#po-download').disabled=false;listEl.innerHTML='<h3>Pages in new order ('+order.length+' of '+pageCount+')</h3>'+order.map(function(p,i){return '<div class="file-meta" style="display:flex;align-items:center;gap:8px;margin:6px 0"><span style="flex:1">Position '+(i+1)+' — original page '+(p+1)+(rots[p]?' · rotated '+rots[p]+'°':'')+'</span><button class="btn secondary" data-act="up" data-i="'+i+'" '+(i===0?'disabled':'')+'>↑ Up</button><button class="btn secondary" data-act="down" data-i="'+i+'" '+(i===order.length-1?'disabled':'')+'>↓ Down</button><button class="btn secondary" data-act="rot" data-i="'+i+'">↻ Rotate</button><button class="btn secondary" data-act="del" data-i="'+i+'">Remove</button></div>'}).join('');listEl.querySelectorAll('button[data-act]').forEach(function(b){b.onclick=function(){var i=+b.dataset.i,act=b.dataset.act;if(act==='up'&&i>0){var tmp=order[i-1];order[i-1]=order[i];order[i]=tmp}if(act==='down'&&i<order.length-1){var tmp2=order[i+1];order[i+1]=order[i];order[i]=tmp2}if(act==='rot'){var p=order[i];rots[p]=(rots[p]+90)%360}if(act==='del'){order.splice(i,1)}renderList()}})}$('#po-file').addEventListener('change',async function(){errEl.innerHTML='';$('#po-result').textContent='';var f=this.files[0];if(!f)return;theFile=f;if(!window.PDFLib){errEl.innerHTML='<div class="error">PDF library could not load — check your connection and retry.</div>';return}try{var buf=await pdfReadBuf(f);var doc=await PDFLib.PDFDocument.load(buf);pageCount=doc.getPageCount();order=[];rots=[];origRots=[];for(var i=0;i<pageCount;i++){order.push(i);rots.push(0);origRots.push(doc.getPages()[i].getRotation().angle||0)}renderList()}catch(e){errEl.innerHTML='<div class="error">Could not read this PDF. Make sure it is a valid, unencrypted PDF.</div>'}});$('#po-download').addEventListener('click',async function(){var out=$('#po-result');if(!theFile||!order.length)return;try{var buf=await pdfReadBuf(theFile);var src=await PDFLib.PDFDocument.load(buf);var doc=await PDFLib.PDFDocument.create();var copied=await doc.copyPages(src,order);copied.forEach(function(pg,i){var srcIdx=order[i];if(rots[srcIdx])pg.setRotation(PDFLib.degrees(((origRots[srcIdx]+rots[srcIdx])%360+360)%360));doc.addPage(pg)});var bytesOut=await doc.save();pdfDownload(bytesOut,'organized.pdf');out.textContent='Done — your organized PDF ('+order.length+' pages) has downloaded.';toast('Organized PDF downloaded.')}catch(e){out.textContent='Something went wrong building the PDF. Please try again.'}})}
function speechToTextTool(t){toolShell(t,`<div class="field"><label class="label" for="st-lang">Language</label><select class="select" id="st-lang"><option value="en-US" selected>English (US)</option><option value="en-GB">English (UK)</option><option value="ur-PK">Urdu (Pakistan)</option><option value="hi-IN">Hindi (India)</option><option value="ar-SA">Arabic (Saudi Arabia)</option><option value="es-ES">Spanish</option><option value="fr-FR">French</option><option value="de-DE">German</option></select></div><div class="actions"><button class="btn primary" id="st-start">🎤 Start dictation</button><button class="btn secondary" id="st-stop" disabled>Stop</button></div><div class="result" id="st-status">Press Start dictation and speak. Works best in Chrome or Edge with a microphone.</div><div class="field"><label class="label" for="st-text">Your text</label><textarea class="textarea" id="st-text" style="min-height:160px" placeholder="Your dictated text appears here — you can edit it freely."></textarea></div><div class="file-meta" id="st-count"></div><div class="actions"><button class="btn primary" id="st-copy">Copy text</button><button class="btn secondary" id="st-download">Download .txt</button><button class="btn secondary" id="st-clear">Clear</button></div>`,`Choose your language, press Start dictation, allow microphone access, and speak clearly. Recognition is done by your browser built-in speech service; the text itself stays on this page.`,['text-to-speech','word-counter','voice-recorder']);var SR=window.SpeechRecognition||window.webkitSpeechRecognition;var statusEl=$('#st-status'),ta=$('#st-text'),rec=null,listening=false,finalText='';function count(){var s=ta.value.trim();$('#st-count').textContent=(s?s.split(/\s+/).length:0)+' words · '+ta.value.length+' characters'}ta.oninput=function(){finalText=ta.value;count()};count();if(!SR){statusEl.innerHTML='<strong>Not supported in this browser.</strong> Speech recognition needs Chrome or Edge. You can still type or paste text above and use Copy or Download.';$('#st-start').disabled=true;return}function start(){rec=new SR();rec.lang=$('#st-lang').value;rec.continuous=true;rec.interimResults=true;finalText=ta.value?ta.value.replace(/\s+$/,'')+' ':'';rec.onresult=function(ev){var interim='';for(var i=ev.resultIndex;i<ev.results.length;i++){var r=ev.results[i];if(r.isFinal){finalText+=r[0].transcript+' '}else interim+=r[0].transcript}ta.value=finalText+interim;count()};rec.onerror=function(ev){if(ev.error==='not-allowed'||ev.error==='service-not-allowed'){listening=false;statusEl.textContent='Microphone access was blocked. Allow the microphone for this site in your browser settings, then try again.';$('#st-start').disabled=false;$('#st-stop').disabled=true}else if(ev.error==='no-speech'){statusEl.textContent='No speech heard — keep speaking, or check your microphone.'}};rec.onend=function(){if(listening){try{rec.start()}catch(e){}}else{statusEl.textContent='Stopped. Your text is ready below.'}};try{rec.start();listening=true;statusEl.textContent='Listening… speak now. Press Stop when you are done.';$('#st-start').disabled=true;$('#st-stop').disabled=false}catch(e){statusEl.textContent='Could not start recognition.'}}$('#st-start').onclick=start;$('#st-stop').onclick=function(){listening=false;$('#st-start').disabled=false;$('#st-stop').disabled=true;if(rec){try{rec.stop()}catch(e){}}};$('#st-copy').onclick=function(){copy(ta.value)};$('#st-download').onclick=function(){downloadText(ta.value,'hectool-speech-to-text.txt')};$('#st-clear').onclick=function(){ta.value='';finalText='';count();ta.focus()}}
function jsonCsvTool(t){toolShell(t,`<div class="field"><label class="label" for="jc-in">JSON input</label><textarea class="textarea" id="jc-in" style="min-height:150px" placeholder='[{"name":"Ali","age":30},{"name":"Sara","age":25}]'></textarea></div><div class="field"><label class="label" for="jc-file">…or choose a .json file</label><input class="input" id="jc-file" type="file" accept=".json,application/json"></div><div id="jc-error"></div><div class="actions"><button class="btn primary" id="jc-run">Convert to CSV</button></div><div class="field"><label class="label" for="jc-out">CSV output</label><textarea class="textarea" id="jc-out" style="min-height:150px" readonly placeholder="Your CSV appears here"></textarea></div><div class="actions"><button class="btn primary" id="jc-copy">Copy CSV</button><button class="btn secondary" id="jc-download">Download .csv</button></div>`,`Paste a JSON array of objects (or a single object). All keys found across the objects become the CSV columns; values with commas or quotes are quoted safely.`,['csv-to-json-converter','json-formatter','text-diff']);function run(){var e=$('#jc-error');e.innerHTML='';try{$('#jc-out').value=jsonToCsvText($('#jc-in').value)}catch(ex){e.innerHTML='<div class="error">Invalid JSON: '+esc(ex.message)+'</div>'}}$('#jc-run').onclick=run;$('#jc-file').onchange=function(){var f=this.files[0];if(!f)return;var r=new FileReader();r.onload=function(){$('#jc-in').value=r.result;run()};r.readAsText(f)};$('#jc-copy').onclick=function(){copy($('#jc-out').value)};$('#jc-download').onclick=function(){downloadText($('#jc-out').value,'hectool-data.csv')}}
