function onlineNotepadTool(t){toolShell(t,`<div class="field"><label class="label" for="np-text">Your notes</label><textarea class="textarea" id="np-text" style="min-height:300px" placeholder="Start typing — your notes save automatically in this browser…"></textarea></div><div class="file-meta"><span id="np-count">0 words · 0 characters</span> · <span id="np-saved">Not saved yet</span></div><div class="actions"><button class="btn primary" id="np-download">Download .txt</button><button class="btn secondary" id="np-copy">Copy all</button><button class="btn secondary" id="np-clear">Clear</button></div>`,`Just type — everything is saved automatically to this browser on this device (local storage), so your note is still here when you come back. It is not synced or uploaded anywhere; clearing your browser data erases it, so download anything important.`,['word-counter','markdown-editor','speech-to-text']);var KEY='hectool-notepad-v1';var ta=$('#np-text');try{ta.value=localStorage.getItem(KEY)||'';if(ta.value)$('#np-saved').textContent='Restored from this browser'}catch(e){}function stats(){var s=ta.value.trim();$('#np-count').textContent=(s?s.split(/\s+/).length:0)+' words · '+ta.value.length+' characters'}ta.oninput=function(){stats();try{localStorage.setItem(KEY,ta.value);$('#np-saved').textContent='Saved ✓ '+new Date().toLocaleTimeString()}catch(e){$('#np-saved').textContent='Could not save (storage unavailable)'}};stats();$('#np-download').onclick=function(){downloadText(ta.value,'hectool-note.txt')};$('#np-copy').onclick=function(){copy(ta.value)};$('#np-clear').onclick=function(){if(!ta.value)return;if(confirm('Clear the whole note? This cannot be undone.')){ta.value='';ta.oninput();ta.focus()}}}
